  'Allow the microphone for FieldOS in Settings, then come back.': 'Settings-ൽ FieldOS-ന് മൈക്രോഫോൺ അനുവദിച്ച് തിരികെ വരൂ.',
  'Open Settings': 'Settings തുറക്കുക',
  'Install or update the Google app from the Play Store, then try again. You can also type the report.': 'Play Store-ൽ നിന്ന് Google ആപ്പ് ഇൻസ്റ്റാൾ ചെയ്യുകയോ അപ്ഡേറ്റ് ചെയ്യുകയോ ചെയ്ത് വീണ്ടും ശ്രമിക്കുക. റിപ്പോർട്ട് ടൈപ്പ് ചെയ്യാനും കഴിയും.',
  'Update the Google app from the Play Store, pick another language above, or type the report.': 'Play Store-ൽ നിന്ന് Google ആപ്പ് അപ്ഡേറ്റ് ചെയ്യുക, മുകളിൽ മറ്റൊരു ഭാഷ തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ റിപ്പോർട്ട് ടൈപ്പ് ചെയ്യുക.',
  'Nothing was heard yet. Tap the mic and speak, or type the report.': 'ഇതുവരെ ഒന്നും കേട്ടില്ല. മൈക്ക് ടാപ്പ് ചെയ്ത് സംസാരിക്കുക, അല്ലെങ്കിൽ റിപ്പോർട്ട് ടൈപ്പ് ചെയ്യുക.',
