  'The language you usually speak your daily reports in. You can still change it each time.': 'നിങ്ങൾ സാധാരണ ദിവസ റിപ്പോർട്ടുകൾ പറയുന്ന ഭാഷ. ഓരോ തവണയും ഇത് മാറ്റാം.',
  'Sarvam key saved': 'Sarvam കീ സേവ് ചെയ്തു',
