  'FieldOS Pro: manage, cancel or restore': 'FieldOS Pro: മാനേജ് ചെയ്യുക, റദ്ദാക്കുക അല്ലെങ്കിൽ പുനഃസ്ഥാപിക്കുക',
  'App language': 'ആപ്പ് ഭാഷ',
