  'Set. Used only on phones that cannot recognise the chosen language.': 'സെറ്റ് ചെയ്തു. തിരഞ്ഞെടുത്ത ഭാഷ തിരിച്ചറിയാൻ കഴിയാത്ത ഫോണുകളിൽ മാത്രം ഉപയോഗിക്കും.',
  'Not set. Voice reports use the phone itself, free and offline.': 'സെറ്റ് ചെയ്തിട്ടില്ല. വോയ്സ് റിപ്പോർട്ടുകൾ ഫോൺ തന്നെ ഉപയോഗിക്കുന്നു, സൗജന്യമായും ഓഫ്‌ലൈനായും.',
  'Open-source licences': 'ഓപ്പൺ സോഴ്സ് ലൈസൻസുകൾ',
  'Version': 'പതിപ്പ്',
  'Current password': 'ഇപ്പോഴത്തെ പാസ്‌വേഡ്',
  'New password': 'പുതിയ പാസ്‌വേഡ്',
  'Voice reports use the phone\'s own speech recognition, free and offline when the language pack is on the phone. Only phones that cannot recognise the chosen language at all send a recording to Sarvam AI (sarvam.ai), which needs a key from your Sarvam account and is billed by Sarvam.': 'വോയ്സ് റിപ്പോർട്ടുകൾ ഫോണിന്റെ സ്വന്തം സ്പീച്ച് റെക്കഗ്നിഷൻ ഉപയോഗിക്കുന്നു, ഭാഷാ പാക്ക് ഫോണിലുണ്ടെങ്കിൽ സൗജന്യമായും ഓഫ്‌ലൈനായും. തിരഞ്ഞെടുത്ത ഭാഷ ഒട്ടും തിരിച്ചറിയാൻ കഴിയാത്ത ഫോണുകൾ മാത്രമേ റെക്കോർഡിംഗ് Sarvam AI-ലേക്ക് (sarvam.ai) അയയ്ക്കൂ; അതിന് നിങ്ങളുടെ Sarvam അക്കൗണ്ടിൽ നിന്നുള്ള ഒരു കീ വേണം, ചാർജ് Sarvam ഈടാക്കും.',
