  'Trade': 'ട്രേഡ്',
  'Please describe what went wrong in a few words.': 'എന്താണ് തെറ്റിയതെന്ന് കുറച്ച് വാക്കുകളിൽ വിവരിക്കുക.',
  'Thank you. Your report was sent to the FieldOS team.': 'നന്ദി. നിങ്ങളുടെ റിപ്പോർട്ട് FieldOS ടീമിന് അയച്ചു.',
  'No internet right now. Your report is saved and will be sent automatically.': 'ഇപ്പോൾ ഇന്റർനെറ്റ് ഇല്ല. നിങ്ങളുടെ റിപ്പോർട്ട് സേവ് ചെയ്തു, അത് തനിയെ അയയ്ക്കും.',
  'Tell us what happened and what you expected. We read every report.': 'എന്ത് സംഭവിച്ചു, നിങ്ങൾ എന്താണ് പ്രതീക്ഷിച്ചത് എന്ന് പറയൂ. ഓരോ റിപ്പോർട്ടും ഞങ്ങൾ വായിക്കുന്നു.',
  'What went wrong?': 'എന്താണ് തെറ്റിയത്?',
  'Your email (optional, so we can reply)': 'നിങ്ങളുടെ ഇമെയിൽ (ഓപ്ഷണൽ, മറുപടി നൽകാൻ)',
  'The app version, phone type and the last few error messages are attached to help us fix it. No project data, photos or contacts are sent.': 'ഇത് പരിഹരിക്കാൻ സഹായിക്കുന്നതിന് ആപ്പ് പതിപ്പ്, ഫോൺ തരം, അവസാനത്തെ ചില എറർ സന്ദേശങ്ങൾ എന്നിവ ചേർക്കുന്നു. പ്രോജക്റ്റ് ഡാറ്റ, ഫോട്ടോകൾ, കോൺടാക്റ്റുകൾ എന്നിവ അയയ്ക്കില്ല.',
  'Send report': 'റിപ്പോർട്ട് അയയ്ക്കുക',
  'Delete your cloud account?': 'നിങ്ങളുടെ ക്ലൗഡ് അക്കൗണ്ട് ഡിലീറ്റ് ചെയ്യണോ?',
  'Delete account': 'അക്കൗണ്ട് ഡിലീറ്റ് ചെയ്യുക',
