  'Back to sign in': 'സൈൻ ഇന്നിലേക്ക് മടങ്ങുക',
  'Got a link instead of a code? Open it, then come back and sign in.': 'കോഡിന് പകരം ലിങ്ക് ആണോ കിട്ടിയത്? അത് തുറന്ന്, തിരികെ വന്ന് സൈൻ ഇൻ ചെയ്യുക.',
  'You become the owner. Your team joins with a code you share from here.': 'നിങ്ങൾ ഉടമയാകും. ഇവിടെ നിന്ന് നിങ്ങൾ ഷെയർ ചെയ്യുന്ന കോഡ് ഉപയോഗിച്ച് ടീം ചേരും.',
