  'Ask the owner for the join code shown on their Team & sync screen.': 'ഉടമയുടെ Team & sync സ്ക്രീനിൽ കാണിക്കുന്ന ജോയിൻ കോഡിനായി അവരോട് ചോദിക്കുക.',
