  'Try a sample site first': 'ആദ്യം ഒരു സാമ്പിൾ സൈറ്റ് പരീക്ഷിക്കൂ',
  'A sample site to try things on. It stays on this phone and your team never sees it.': 'കാര്യങ്ങൾ പരീക്ഷിച്ചുനോക്കാൻ ഒരു സാമ്പിൾ സൈറ്റ്. ഇത് ഈ ഫോണിൽ മാത്രം ഇരിക്കും, നിങ്ങളുടെ ടീം ഇത് കാണില്ല.',
  'Remove the sample site?': 'സാമ്പിൾ സൈറ്റ് നീക്കം ചെയ്യണോ?',
  'Its tasks, labour, reports and money are deleted from this phone. Your own projects are not touched.': 'അതിന്റെ ടാസ്കുകൾ, തൊഴിലാളികൾ, റിപ്പോർട്ടുകൾ, പണം എന്നിവ ഈ ഫോണിൽ നിന്ന് ഡിലീറ്റ് ആകും. നിങ്ങളുടെ സ്വന്തം പ്രോജക്റ്റുകളെ ബാധിക്കില്ല.',
