  'Sign in with Apple': 'Apple ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക',
  'Apple sign-in did not go through. Please try again.': 'Apple സൈൻ ഇൻ നടന്നില്ല. വീണ്ടും ശ്രമിക്കുക.',
  'Apple did not share an email address. Please try again, or use a username and password.': 'Apple ഇമെയിൽ വിലാസം ഷെയർ ചെയ്തില്ല. വീണ്ടും ശ്രമിക്കുക, അല്ലെങ്കിൽ യൂസർനെയിമും പാസ്‌വേഡും ഉപയോഗിക്കുക.',
  'Continue with Google': 'Google ഉപയോഗിച്ച് തുടരുക',
  'More details (optional)': 'കൂടുതൽ വിവരങ്ങൾ (ഓപ്ഷണൽ)',
  'Report': 'റിപ്പോർട്ട് ചെയ്യുക',
  'Report this message': 'ഈ സന്ദേശം റിപ്പോർട്ട് ചെയ്യുക',
  'Thanks. We review reports within 24 hours.': 'നന്ദി. 24 മണിക്കൂറിനുള്ളിൽ ഞങ്ങൾ റിപ്പോർട്ടുകൾ പരിശോധിക്കും.',
  'The FieldOS team reviews it. The sender is not told who reported it.': 'FieldOS ടീം ഇത് പരിശോധിക്കും. ആരാണ് റിപ്പോർട്ട് ചെയ്തതെന്ന് അയച്ചയാളെ അറിയിക്കില്ല.',
  'What is wrong with it?': 'ഇതിൽ എന്താണ് തെറ്റ്?',
  'You reported this message.': 'നിങ്ങൾ ഈ സന്ദേശം റിപ്പോർട്ട് ചെയ്തു.',
  'Abuse or threats': 'അധിക്ഷേപം അല്ലെങ്കിൽ ഭീഷണി',
  'Spam or fraud': 'സ്പാം അല്ലെങ്കിൽ തട്ടിപ്പ്',
  'Sexual or offensive content': 'ലൈംഗികമോ അപമാനകരമോ ആയ ഉള്ളടക്കം',
  'Something else': 'മറ്റെന്തെങ്കിലും',
  'Sign in under Team & sync to report a message.': 'ഒരു സന്ദേശം റിപ്പോർട്ട് ചെയ്യാൻ Team & sync-ൽ സൈൻ ഇൻ ചെയ്യുക.',
  'The report did not go through. Check the internet and try again.': 'റിപ്പോർട്ട് അയയ്ക്കാനായില്ല. ഇന്റർനെറ്റ് പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.',
  'Google sign-in did not go through. Please try again.': 'Google സൈൻ ഇൻ നടന്നില്ല. വീണ്ടും ശ്രമിക്കുക.',
  'Google sign-in is not ready on this version of the app. Use your username and password for now.': 'ആപ്പിന്റെ ഈ പതിപ്പിൽ Google സൈൻ ഇൻ തയ്യാറായിട്ടില്ല. ഇപ്പോൾ നിങ്ങളുടെ യൂസർനെയിമും പാസ്‌വേഡും ഉപയോഗിക്കുക.',
  'Add worker {name} at {site}': '{site}-ൽ തൊഴിലാളി {name}-നെ ചേർക്കുക',
  'Add ₹5,000 spent on cement': 'സിമന്റിന് ചെലവായ ₹5,000 ചേർക്കുക',
  'Ask FieldOS': 'FieldOS-നോട് ചോദിക്കുക',
  'Ask or tell FieldOS anything…': 'FieldOS-നോട് എന്തും ചോദിക്കൂ അല്ലെങ്കിൽ പറയൂ…',
  'Could not save': 'സേവ് ചെയ്യാനായില്ല',
  'Expense {amount} for {category} at {site}': '{site}-ൽ {category}-ന് {amount} ചെലവ്',
  'Home': 'ഹോം',
  'How do I make a bill for my client?': 'എന്റെ ക്ലയന്റിന് ബിൽ എങ്ങനെ ഉണ്ടാക്കാം?',
  'How much did I spend this month?': 'ഈ മാസം ഞാൻ എത്ര ചെലവാക്കി?',
  'Just say it: "Add ₹5,000 for cement", "Who came today?"': 'വെറുതെ പറഞ്ഞാൽ മതി: "സിമന്റിന് ₹5,000 ചേർക്കുക", "ഇന്ന് ആരൊക്കെ വന്നു?"',
  'Mark all workers present': 'എല്ലാ തൊഴിലാളികളെയും ഹാജരായി മാർക്ക് ചെയ്യുക',
  'Mark done: {title}': 'പൂർത്തിയായി മാർക്ക് ചെയ്യുക: {title}',
  'Mark present at {site}: {names}': '{site}-ൽ ഹാജരായി മാർക്ക് ചെയ്യുക: {names}',
  'Material received at {site}: {qty} {material}': '{site}-ൽ ലഭിച്ച മെറ്റീരിയൽ: {qty} {material}',
  'Material used at {site}: {qty} {material}': '{site}-ൽ ഉപയോഗിച്ച മെറ്റീരിയൽ: {qty} {material}',
  'Namaste! What should I do?': 'നമസ്കാരം! ഞാൻ എന്ത് ചെയ്യണം?',
  'Namaste, {name}! What should I do?': 'നമസ്കാരം, {name}! ഞാൻ എന്ത് ചെയ്യണം?',
  'New chat': 'പുതിയ ചാറ്റ്',
  'New project: {name}': 'പുതിയ പ്രോജക്റ്റ്: {name}',
  'New task at {site}: {title}': '{site}-ൽ പുതിയ ടാസ്ക്: {title}',
  'Not saved': 'സേവ് ചെയ്തില്ല',
  'Open {screen}': '{screen} തുറക്കുക',
  'Payment received {amount} from {party} at {site}': '{site}-ൽ {party}-ൽ നിന്ന് {amount} പേയ്മെന്റ് ലഭിച്ചു',
  'Problem at {site}: {text}': '{site}-ൽ പ്രശ്നം: {text}',
  'Read aloud': 'ഉറക്കെ വായിക്കുക',
  'Read answers aloud': 'ഉത്തരങ്ങൾ ഉറക്കെ വായിക്കുക',
  'Save this?': 'ഇത് സേവ് ചെയ്യണോ?',
  'Saved': 'സേവ് ചെയ്തു',
  'Set {title} to {p}%': '{title} {p}% ആക്കുക',
  'Sign in once to use the assistant': 'അസിസ്റ്റന്റ് ഉപയോഗിക്കാൻ ഒരിക്കൽ സൈൻ ഇൻ ചെയ്യുക',
  'Sign in to Team & sync': 'Team & sync-ൽ സൈൻ ഇൻ ചെയ്യുക',
  'Something went wrong: {error}': 'എന്തോ പിശക് സംഭവിച്ചു: {error}',
  'Speak': 'സംസാരിക്കുക',
  'Speak to FieldOS': 'FieldOS-നോട് സംസാരിക്കുക',
  'Stop reading answers aloud': 'ഉത്തരങ്ങൾ ഉറക്കെ വായിക്കുന്നത് നിർത്തുക',
  'Tap Save or Cancel above first': 'ആദ്യം മുകളിലുള്ള സേവ് അല്ലെങ്കിൽ റദ്ദാക്കുക ടാപ്പ് ചെയ്യുക',
  'Tell me in your own words, by typing or with the mic. I can add expenses, attendance, tasks, reports and more, and answer questions about your sites. I always ask before saving anything.': 'ടൈപ്പ് ചെയ്തോ മൈക്ക് ഉപയോഗിച്ചോ നിങ്ങളുടെ സ്വന്തം വാക്കുകളിൽ പറയൂ. എനിക്ക് ചെലവുകൾ, ഹാജർ, ടാസ്കുകൾ, റിപ്പോർട്ടുകൾ തുടങ്ങിയവ ചേർക്കാനും നിങ്ങളുടെ സൈറ്റുകളെക്കുറിച്ചുള്ള ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകാനും കഴിയും. എന്തെങ്കിലും സേവ് ചെയ്യുന്നതിന് മുമ്പ് ഞാൻ എപ്പോഴും ചോദിക്കും.',
  'That took too many steps. Try asking for one thing at a time.': 'അതിന് ഒരുപാട് ഘട്ടങ്ങൾ വേണ്ടിവന്നു. ഒരു സമയം ഒരു കാര്യം ചോദിച്ചുനോക്കൂ.',
  'The answer was cut short. Please ask again in fewer words.': 'ഉത്തരം ഇടയ്ക്ക് മുറിഞ്ഞുപോയി. കുറച്ച് വാക്കുകളിൽ വീണ്ടും ചോദിക്കൂ.',
  'The assistant can\'t help with that one. Try asking another way.': 'അസിസ്റ്റന്റിന് അതിൽ സഹായിക്കാനാവില്ല. മറ്റൊരു രീതിയിൽ ചോദിച്ചുനോക്കൂ.',
  'The assistant thinks on FieldOS\'s server, so it needs your FieldOS account and internet. Your site data stays on this phone; only what you ask, and what is needed to answer it, is sent.': 'അസിസ്റ്റന്റ് FieldOS-ന്റെ സെർവറിലാണ് പ്രവർത്തിക്കുന്നത്, അതിനാൽ നിങ്ങളുടെ FieldOS അക്കൗണ്ടും ഇന്റർനെറ്റും വേണം. നിങ്ങളുടെ സൈറ്റ് ഡാറ്റ ഈ ഫോണിൽ തന്നെ ഇരിക്കും; നിങ്ങൾ ചോദിക്കുന്നതും ഉത്തരം നൽകാൻ ആവശ്യമുള്ളതും മാത്രമേ അയയ്ക്കൂ.',
  'Today\'s report for {site}: {text}': '{site}-ന്റെ ഇന്നത്തെ റിപ്പോർട്ട്: {text}',
  'Type or speak. I will do it in the app.': 'ടൈപ്പ് ചെയ്യുക അല്ലെങ്കിൽ പറയുക. ഞാൻ ആപ്പിൽ അത് ചെയ്യാം.',
  'What happened on my sites today?': 'ഇന്ന് എന്റെ സൈറ്റുകളിൽ എന്ത് നടന്നു?',
  'Which tasks are late?': 'ഏതൊക്കെ ടാസ്കുകളാണ് വൈകിയത്?',
  'Working on it…': 'ചെയ്തുകൊണ്ടിരിക്കുന്നു…',
  'Write today\'s daily report': 'ഇന്നത്തെ ദിവസ റിപ്പോർട്ട് എഴുതുക',
  'Sign in to Team & sync once to use the assistant.': 'അസിസ്റ്റന്റ് ഉപയോഗിക്കാൻ ഒരിക്കൽ Team & sync-ൽ സൈൻ ഇൻ ചെയ്യുക.',
  'Sign in to FieldOS again to use the assistant.': 'അസിസ്റ്റന്റ് ഉപയോഗിക്കാൻ FieldOS-ൽ വീണ്ടും സൈൻ ഇൻ ചെയ്യുക.',
  'The assistant comes with the FieldOS plan. Start or renew it in My subscription.': 'അസിസ്റ്റന്റ് FieldOS പ്ലാനിനൊപ്പം വരുന്നു. My subscription-ൽ അത് തുടങ്ങുകയോ പുതുക്കുകയോ ചെയ്യുക.',
  'You\'ve used this month\'s assistant allowance. It starts again on the 1st. Everything else in FieldOS works as usual.': 'ഈ മാസത്തെ അസിസ്റ്റന്റ് പരിധി നിങ്ങൾ ഉപയോഗിച്ചുകഴിഞ്ഞു. 1-ാം തീയതി അത് വീണ്ടും തുടങ്ങും. FieldOS-ലെ മറ്റെല്ലാം സാധാരണ പോലെ പ്രവർത്തിക്കും.',
  'This month\'s voice allowance is used up. Please type, or use the phone\'s own voice typing.': 'ഈ മാസത്തെ വോയ്സ് പരിധി കഴിഞ്ഞു. ദയവായി ടൈപ്പ് ചെയ്യുക, അല്ലെങ്കിൽ ഫോണിന്റെ സ്വന്തം വോയ്സ് ടൈപ്പിംഗ് ഉപയോഗിക്കുക.',
  'Just ask FieldOS': 'FieldOS-നോട് ചോദിച്ചാൽ മതി',
  'Not sure where something is? Tap Ask FieldOS at the top and type or speak, like "add 5000 for cement". It does the work and asks you to tap Save first.': 'എന്തെങ്കിലും എവിടെയാണെന്ന് ഉറപ്പില്ലേ? മുകളിലുള്ള Ask FieldOS ടാപ്പ് ചെയ്ത് "സിമന്റിന് 5000 ചേർക്കുക" എന്നത് പോലെ ടൈപ്പ് ചെയ്യുകയോ പറയുകയോ ചെയ്യുക. അത് ജോലി ചെയ്യും, ആദ്യം സേവ് ടാപ്പ് ചെയ്യാൻ നിങ്ങളോട് ചോദിക്കും.',
  '{n}% of this month\'s assistant use is left': 'ഈ മാസത്തെ അസിസ്റ്റന്റ് ഉപയോഗത്തിന്റെ {n}% ബാക്കിയുണ്ട്',
  'You\'ve used the assistant a lot today. It will be ready again tomorrow.': 'ഇന്ന് നിങ്ങൾ അസിസ്റ്റന്റ് ഒരുപാട് ഉപയോഗിച്ചു. നാളെ അത് വീണ്ടും തയ്യാറാകും.',
  'No internet. The assistant needs internet; everything else in FieldOS works offline.': 'ഇന്റർനെറ്റ് ഇല്ല. അസിസ്റ്റന്റിന് ഇന്റർനെറ്റ് വേണം; FieldOS-ലെ മറ്റെല്ലാം ഓഫ്‌ലൈനായി പ്രവർത്തിക്കും.',
  'The assistant could not answer just now. Please try again in a minute.': 'അസിസ്റ്റന്റിന് ഇപ്പോൾ ഉത്തരം നൽകാനായില്ല. ഒരു മിനിറ്റിന് ശേഷം വീണ്ടും ശ്രമിക്കുക.',
  'The assistant is not switched on yet. Please try again later.': 'അസിസ്റ്റന്റ് ഇതുവരെ ഓൺ ചെയ്തിട്ടില്ല. പിന്നീട് വീണ്ടും ശ്രമിക്കുക.',
  'This chat has grown too long. Start a new chat.': 'ഈ ചാറ്റ് വളരെ നീണ്ടുപോയി. ഒരു പുതിയ ചാറ്റ് തുടങ്ങുക.',
  'The assistant took too long. Check your internet and try again.': 'അസിസ്റ്റന്റ് ഒരുപാട് സമയമെടുത്തു. ഇന്റർനെറ്റ് പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.',
  'Your data': 'നിങ്ങളുടെ ഡാറ്റ',
  'Export all sites to Excel': 'എല്ലാ സൈറ്റുകളും Excel-ലേക്ക് എക്‌സ്‌പോർട്ട് ചെയ്യുക',
  'Every record on this phone, in one file you keep. Free, always.': 'ഈ ഫോണിലെ എല്ലാ രേഖകളും, നിങ്ങൾ സൂക്ഷിക്കുന്ന ഒരു ഫയലിൽ. എപ്പോഴും സൗജന്യം.',
  'Export to Excel': 'Excel-ലേക്ക് എക്‌സ്‌പോർട്ട് ചെയ്യുക',
  'Export my data': 'എന്റെ ഡാറ്റ എക്‌സ്‌പോർട്ട് ചെയ്യുക',
  'Your records stay yours': 'നിങ്ങളുടെ രേഖകൾ നിങ്ങളുടേത് തന്നെ',
  'Everything you entered stays on this phone and is never deleted when a plan ends. Export it to Excel any time, free.': 'നിങ്ങൾ നൽകിയതെല്ലാം ഈ ഫോണിൽ തന്നെ ഇരിക്കും, ഒരു പ്ലാൻ അവസാനിക്കുമ്പോൾ ഒരിക്കലും ഡിലീറ്റ് ആകില്ല. എപ്പോൾ വേണമെങ്കിലും സൗജന്യമായി Excel-ലേക്ക് എക്‌സ്‌പോർട്ട് ചെയ്യാം.',
