  'It stays in the list, struck through, and counts in no total. You can restore it later.': 'അത് വെട്ടിയ നിലയിൽ ലിസ്റ്റിൽ തുടരും, ഒരു മൊത്തത്തിലും കണക്കാക്കില്ല. പിന്നീട് പുനഃസ്ഥാപിക്കാം.',
