  'Note': 'കുറിപ്പ്',
  'Nothing matches these filters.': 'ഈ ഫിൽട്ടറുകളുമായി ഒന്നും ചേരുന്നില്ല.',
  'Only the person who entered this, the owner or a project manager can change it.': 'ഇത് നൽകിയ ആൾക്കോ ഉടമയ്ക്കോ പ്രോജക്റ്റ് മാനേജർക്കോ മാത്രമേ ഇത് മാറ്റാൻ കഴിയൂ.',
  'Paid to': 'ആർക്ക് നൽകി',
