  'Pick dates': 'തീയതികൾ തിരഞ്ഞെടുക്കുക',
  'Reason (e.g. entered twice)': 'കാരണം (ഉദാ. രണ്ട് തവണ നൽകി)',
  'Record each payment the client makes (running bills, advances).': 'ക്ലയന്റ് നൽകുന്ന ഓരോ പേയ്മെന്റും രേഖപ്പെടുത്തുക (ഇടക്കാല പേയ്മെന്റ് അപേക്ഷകൾ, അഡ്വാൻസുകൾ).',
  'Restore entry': 'എൻട്രി പുനഃസ്ഥാപിക്കുക',
