  'Where the money went': 'പണം എവിടെ പോയി',
  'Why cancelled': 'എന്തിന് റദ്ദാക്കി',
  '{n} entries · {total}': '{n} എൻട്രികൾ · {total}',
  '{total} across {n} categories': '{n} വിഭാഗങ്ങളിലായി {total}',
  '1 entry · {total}': '1 എൻട്രി · {total}',
  'A day counts as full at 7 hours on site and half at 3.5 hours, unless it was marked by hand on the day register. Tap a worker to pay wages or an advance.': 'സൈറ്റിൽ 7 മണിക്കൂർ ആയാൽ മുഴുവൻ ദിവസവും 3.5 മണിക്കൂർ ആയാൽ അര ദിവസവും ആയി കണക്കാക്കും, ഡേ രജിസ്റ്ററിൽ കൈകൊണ്ട് മാർക്ക് ചെയ്തിട്ടില്ലെങ്കിൽ. വേതനമോ അഡ്വാൻസോ നൽകാൻ ഒരു തൊഴിലാളിയെ ടാപ്പ് ചെയ്യുക.',
  'A mark replaces what the punches count for that day. Tap a chosen mark again to go back to the punches.': 'ഒരു മാർക്ക് ആ ദിവസത്തെ പഞ്ചുകളുടെ കണക്കിന് പകരമാകും. പഞ്ചുകളിലേക്ക് മടങ്ങാൻ തിരഞ്ഞെടുത്ത മാർക്ക് വീണ്ടും ടാപ്പ് ചെയ്യുക.',
  'Absent': 'ഹാജരില്ല',
  'Add workers with their trade and daily wage, then mark their days here.': 'തൊഴിലാളികളെ അവരുടെ ട്രേഡും ദിവസ വേതനവും ചേർത്ത് ചേർക്കുക, എന്നിട്ട് അവരുടെ ദിവസങ്ങൾ ഇവിടെ മാർക്ക് ചെയ്യുക.',
