  'What is in the store today, before any GRN in FieldOS. It is not counted as money spent.': 'FieldOS-ൽ ഏതെങ്കിലും GRN-ന് മുമ്പ്, ഇന്ന് സ്റ്റോറിൽ ഉള്ളത്. ഇത് ചെലവായ പണമായി കണക്കാക്കില്ല.',
  'When you add a machine, switch on "Hired from someone" to keep it here.': 'ഒരു മെഷീൻ ചേർക്കുമ്പോൾ, അത് ഇവിടെ സൂക്ഷിക്കാൻ "മറ്റൊരാളിൽ നിന്ന് വാടകയ്ക്ക് എടുത്തത്" ഓൺ ചെയ്യുക.',
