  'Advance with them {amount}': 'അവരുടെ കയ്യിലുള്ള അഡ്വാൻസ് {amount}',
  'Bills and reports': 'ബില്ലുകളും റിപ്പോർട്ടുകളും',
  'Company logo': 'കമ്പനി ലോഗോ',
  'Could not open the photos.': 'ഫോട്ടോകൾ തുറക്കാനായില്ല.',
  'Deliveries from this supplier and payments made to them appear here. Pick them as "Paid to" when you add an expense.': 'ഈ സപ്ലയറിൽ നിന്നുള്ള ഡെലിവറികളും അവർക്ക് നൽകിയ പേയ്മെന്റുകളും ഇവിടെ കാണാം. ചെലവ് ചേർക്കുമ്പോൾ അവരെ "ആർക്ക് നൽകി" ആയി തിരഞ്ഞെടുക്കുക.',
  'Logo saved. It goes on your bills, vouchers and daily reports.': 'ലോഗോ സേവ് ചെയ്തു. അത് നിങ്ങളുടെ ബില്ലുകളിലും വൗച്ചറുകളിലും ദിവസ റിപ്പോർട്ടുകളിലും വരും.',
  'On your bills, vouchers and daily reports. Tap to change.': 'നിങ്ങളുടെ ബില്ലുകളിലും വൗച്ചറുകളിലും ദിവസ റിപ്പോർട്ടുകളിലും. മാറ്റാൻ ടാപ്പ് ചെയ്യുക.',
  'Opening balance': 'ഓപ്പണിംഗ് ബാലൻസ്',
  'Opening balance: {amount}': 'ഓപ്പണിംഗ് ബാലൻസ്: {amount}',
