  'Settled': 'തീർത്തു',
  'That file is not a picture. Pick a PNG or JPG.': 'ആ ഫയൽ ഒരു ചിത്രമല്ല. PNG അല്ലെങ്കിൽ JPG തിരഞ്ഞെടുക്കുക.',
  'We owe them': 'നമ്മൾ അവർക്ക് കൊടുക്കാനുണ്ട്',
