  'First line is the title. E.g. "Client wants the kitchen window 4 ft wide"': 'ആദ്യ വരിയാണ് തലക്കെട്ട്. ഉദാ. "അടുക്കള ജനൽ 4 ft വീതിയിൽ വേണമെന്ന് ക്ലയന്റ്"',
  'It is deleted from this phone. This can\'t be undone.': 'ഇത് ഈ ഫോണിൽ നിന്ന് ഡിലീറ്റ് ആകും. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.',
  'Keep what was agreed with the client, sizes to check and numbers to call. Everyone on this site sees them.': 'ക്ലയന്റുമായി സമ്മതിച്ച കാര്യങ്ങൾ, പരിശോധിക്കേണ്ട അളവുകൾ, വിളിക്കേണ്ട നമ്പറുകൾ എന്നിവ സൂക്ഷിക്കുക. ഈ സൈറ്റിലെ എല്ലാവർക്കും ഇവ കാണാം.',
  'New note': 'പുതിയ കുറിപ്പ്',
  'No note has these words.': 'ഈ വാക്കുകളുള്ള കുറിപ്പില്ല.',
  'No notes yet': 'ഇതുവരെ കുറിപ്പുകളില്ല',
  'Note removed.': 'കുറിപ്പ് നീക്കം ചെയ്തു.',
  'Notes': 'കുറിപ്പുകൾ',
  'Only the person who wrote this, the owner or a project manager can change it.': 'ഇത് എഴുതിയ ആൾക്കോ ഉടമയ്ക്കോ പ്രോജക്റ്റ് മാനേജർക്കോ മാത്രമേ ഇത് മാറ്റാൻ കഴിയൂ.',
  'Pin to top': 'മുകളിൽ പിൻ ചെയ്യുക',
