  'Tap to open or share': 'തുറക്കാനോ ഷെയർ ചെയ്യാനോ ടാപ്പ് ചെയ്യുക',
  'The file is deleted from this phone. The expense stays.': 'ഫയൽ ഈ ഫോണിൽ നിന്ന് ഡിലീറ്റ് ആകും. ചെലവ് നിലനിൽക്കും.',
