  '{n} bills are on the phone that added them.': '{n} ബില്ലുകൾ അവ ചേർത്ത ഫോണിലാണ്.',
  '{n} bills attached': '{n} ബില്ലുകൾ ചേർത്തു',
  'Google sign-in did not go through. Check the internet and try again.': 'Google സൈൻ ഇൻ നടന്നില്ല. ഇന്റർനെറ്റ് പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.',
