  'Explore the sample': 'സാമ്പിൾ നോക്കുക',
  'Start my project': 'എന്റെ പ്രോജക്റ്റ് തുടങ്ങുക',
  'Start the tour': 'ടൂർ തുടങ്ങുക',
  '{n} of {total}': '{total}-ൽ {n}',
  'Namaste! I am Mitra, your site buddy': 'നമസ്കാരം! ഞാൻ Mitra, നിങ്ങളുടെ സൈറ്റ് കൂട്ടുകാരൻ',
  'Let me show you one day on a real site: Mr. Reddy\'s G+1 house. It takes two minutes and does not touch your own data.': 'ഒരു യഥാർത്ഥ സൈറ്റിലെ ഒരു ദിവസം ഞാൻ കാണിച്ചുതരാം: Mr. Reddy-യുടെ G+1 വീട്. രണ്ട് മിനിറ്റ് മതി, നിങ്ങളുടെ സ്വന്തം ഡാറ്റയെ ഇത് ബാധിക്കില്ല.',
  'All your sites in one list': 'നിങ്ങളുടെ എല്ലാ സൈറ്റുകളും ഒരു ലിസ്റ്റിൽ',
  'Each site shows its stage and anything running late. Tap a site to open its tasks, labour, money and reports.': 'ഓരോ സൈറ്റും അതിന്റെ ഘട്ടവും വൈകുന്ന കാര്യങ്ങളും കാണിക്കുന്നു. അതിന്റെ ടാസ്കുകൾ, തൊഴിലാളികൾ, പണം, റിപ്പോർട്ടുകൾ തുറക്കാൻ ഒരു സൈറ്റ് ടാപ്പ് ചെയ്യുക.',
  'Plan the day': 'ദിവസം പ്ലാൻ ചെയ്യുക',
  'Tasks show how far each job has got and what is slipping. The plinth beam is late, so it is marked in red before anyone has to ask.': 'ഓരോ ജോലിയും എത്രത്തോളം ആയി, എന്താണ് പിന്നോട്ട് പോകുന്നത് എന്ന് ടാസ്കുകൾ കാണിക്കുന്നു. പ്ലിന്ത് ബീം വൈകിയതിനാൽ, ആരെങ്കിലും ചോദിക്കുന്നതിന് മുമ്പേ അത് ചുവപ്പിൽ കാണിക്കും.',
  'Attendance in two taps': 'രണ്ട് ടാപ്പിൽ ഹാജർ',
  'Punch workers in as they arrive, or mark the whole gang at once. Hours, half days and overtime are worked out for you.': 'തൊഴിലാളികൾ എത്തുമ്പോൾ അവരെ പഞ്ച് ഇൻ ചെയ്യുക, അല്ലെങ്കിൽ മുഴുവൻ സംഘത്തെയും ഒരുമിച്ച് മാർക്ക് ചെയ്യുക. മണിക്കൂറുകൾ, അര ദിവസങ്ങൾ, ഓവർടൈം എന്നിവ നിങ്ങൾക്കായി കണക്കാക്കും.',
  'Cement arrives': 'സിമന്റ് എത്തി',
  'Raise a purchase order, then receive what actually came. A part delivery keeps the order open, and stock updates itself.': 'ഒരു LPO നൽകുക, എന്നിട്ട് ശരിക്കും വന്നത് സ്വീകരിക്കുക. ഭാഗികമായ ഡെലിവറി ആണെങ്കിൽ ഓർഡർ തുറന്നിരിക്കും, സ്റ്റോക്ക് തനിയെ അപ്ഡേറ്റ് ആകും.',
  'Every rupee on site': 'സൈറ്റിലെ ഓരോ ദിർഹവും',
  'Money received, money spent and the balance, by category. Client bills and GST invoices are made here too.': 'ലഭിച്ച പണം, ചെലവായ പണം, ബാക്കി എന്നിവ വിഭാഗം തിരിച്ച്. ക്ലയന്റ് ബില്ലുകളും VAT ഇൻവോയ്സുകളും ഇവിടെ തന്നെ ഉണ്ടാക്കാം.',
  'Problems do not get lost': 'പ്രശ്നങ്ങൾ നഷ്ടപ്പെടില്ല',
  'Cement ran short for the column casting. Raise it once and it stays open, with photos, until someone marks it fixed.': 'കോളം കാസ്റ്റിംഗിന് സിമന്റ് തികഞ്ഞില്ല. ഒരിക്കൽ ഉന്നയിച്ചാൽ, ആരെങ്കിലും പരിഹരിച്ചതായി മാർക്ക് ചെയ്യുന്നത് വരെ ഫോട്ടോകളോടൊപ്പം അത് തുറന്നിരിക്കും.',
  'Speak the daily report': 'ദിവസ റിപ്പോർട്ട് പറയുക',
  'Tap Speak report and just talk, in Telugu, Hindi or English. FieldOS writes the report, adds the day\'s numbers and shares a PDF on WhatsApp.': 'റിപ്പോർട്ട് പറയുക ടാപ്പ് ചെയ്ത് തെലുങ്കിലോ ഹിന്ദിയിലോ ഇംഗ്ലീഷിലോ സംസാരിച്ചാൽ മതി. FieldOS റിപ്പോർട്ട് എഴുതി, ആ ദിവസത്തെ കണക്കുകൾ ചേർത്ത്, WhatsApp-ൽ PDF ഷെയർ ചെയ്യും.',
  'Wages without a calculator': 'കാൽക്കുലേറ്റർ ഇല്ലാതെ വേതനം',
  'The wage sheet adds up each worker\'s days, advances and what is still due, ready to pay or send to the contractor.': 'വേതന ഷീറ്റ് ഓരോ തൊഴിലാളിയുടെയും ദിവസങ്ങൾ, അഡ്വാൻസുകൾ, ഇനിയും നൽകാനുള്ളത് എന്നിവ കൂട്ടിക്കണക്കാക്കുന്നു, നൽകാനോ ലേബർ സപ്ലൈ കമ്പനിക്ക് അയയ്ക്കാനോ തയ്യാർ.',
  'Every site at a glance': 'എല്ലാ സൈറ്റുകളും ഒറ്റനോട്ടത്തിൽ',
  'Owners see spending against budget, progress and open problems across all sites, without a single phone call.': 'ഒരു ഫോൺ കോൾ പോലുമില്ലാതെ, എല്ലാ സൈറ്റുകളിലെയും ബജറ്റിനെതിരെയുള്ള ചെലവ്, പുരോഗതി, തുറന്ന പ്രശ്നങ്ങൾ എന്നിവ ഉടമകൾക്ക് കാണാം.',
  'You are ready!': 'നിങ്ങൾ തയ്യാർ!',
  'Look around the sample site yourself, or start your first real project. You can play this tour again from the menu any time.': 'സാമ്പിൾ സൈറ്റ് സ്വയം ചുറ്റിനോക്കൂ, അല്ലെങ്കിൽ നിങ്ങളുടെ ആദ്യ യഥാർത്ഥ പ്രോജക്റ്റ് തുടങ്ങൂ. മെനുവിൽ നിന്ന് എപ്പോൾ വേണമെങ്കിലും ഈ ടൂർ വീണ്ടും കാണാം.',
  'New here? Take the 2-minute tour': 'പുതിയതാണോ? 2 മിനിറ്റ് ടൂർ കാണൂ',
  'See one full day on a sample site, from attendance to the evening report.': 'ഹാജർ മുതൽ വൈകുന്നേരത്തെ റിപ്പോർട്ട് വരെ, ഒരു സാമ്പിൾ സൈറ്റിലെ ഒരു മുഴുവൻ ദിവസം കാണൂ.',
  '1 new issue': '1 പുതിയ പ്രശ്നം',
  '1 serious issue open': '1 ഗുരുതര പ്രശ്നം തുറന്നിരിക്കുന്നു',
  '1 site needs you': '1 സൈറ്റിന് നിങ്ങളെ ആവശ്യമുണ്ട്',
  'At 7:30 pm, which sites need you and why': 'രാത്രി 7:30-ന്, ഏതൊക്കെ സൈറ്റുകൾക്ക് നിങ്ങളെ ആവശ്യമുണ്ട്, എന്തുകൊണ്ട്',
  'Built from what each site recorded. Pull down to refresh.': 'ഓരോ സൈറ്റും രേഖപ്പെടുത്തിയതിൽ നിന്ന് തയ്യാറാക്കിയത്. പുതുക്കാൻ താഴേക്ക് വലിക്കുക.',
