  'Deliveries and payments to suppliers show here, oldest debts first.': 'സപ്ലയർമാരിൽ നിന്നുള്ള ഡെലിവറികളും അവർക്കുള്ള പേയ്മെന്റുകളും ഇവിടെ കാണാം, ഏറ്റവും പഴയ കടങ്ങൾ ആദ്യം.',
  'Every expense as a payment voucher and every client payment as a receipt, with GST split out.': 'ഓരോ ചെലവും പേയ്മെന്റ് വൗച്ചറായും ഓരോ ക്ലയന്റ് പേയ്മെന്റും രസീതായും, VAT വേർതിരിച്ച്.',
