  'No site area set, so punches are not checked. Set it while standing at the site.': 'സൈറ്റ് ഏരിയ സെറ്റ് ചെയ്തിട്ടില്ല, അതിനാൽ പഞ്ചുകൾ പരിശോധിക്കുന്നില്ല. സൈറ്റിൽ നിൽക്കുമ്പോൾ ഇത് സെറ്റ് ചെയ്യുക.',
  'Not active': 'സജീവമല്ല',
  'Not checked': 'പരിശോധിച്ചിട്ടില്ല',
  'Not started yet': 'ഇതുവരെ തുടങ്ങിയിട്ടില്ല',
  'Nothing is late. Tasks show here when they pass their due date, or when their pace means they will finish after it.': 'ഒന്നും വൈകിയിട്ടില്ല. അവസാന തീയതി കഴിയുമ്പോഴോ, ഇപ്പോഴത്തെ വേഗത്തിൽ അതിനുശേഷം മാത്രം തീരുമെന്ന് കാണുമ്പോഴോ ജോലികൾ ഇവിടെ കാണിക്കും.',
  'On hold': 'നിർത്തിവച്ചു',
  'On site': 'സൈറ്റിൽ',
  'Open': 'തുറന്നത്',
  'Partly passed': 'ഭാഗികമായി പാസായി',
  'Passed': 'പാസായി',
  'Planning': 'ആസൂത്രണം',
  'Punch in {n} of {total}': 'പഞ്ച് ഇൻ {total}-ൽ {n}',
  'Raised {date}': '{date}-ന് ഉന്നയിച്ചു',
  'Report saved, and {n} problems raised as issues.': 'റിപ്പോർട്ട് സേവ് ചെയ്തു, {n} പ്രശ്നങ്ങൾ ഇഷ്യൂ ആയി ചേർത്തു.',
  'Report saved.': 'റിപ്പോർട്ട് സേവ് ചെയ്തു.',
  'Set when they left. Until then each counts as half a day.': 'അവർ പോയ സമയം നൽകുക. അതുവരെ ഓരോന്നും അര ദിവസമായി കണക്കാക്കും.',
  'Show earlier days ({n} more)': 'മുമ്പത്തെ ദിവസങ്ങൾ കാണിക്കുക ({n} എണ്ണം കൂടി)',
  'Site area: within {m} m of the point you set. Punches outside it are marked.': 'സൈറ്റ് ഏരിയ: നിങ്ങൾ സെറ്റ് ചെയ്ത സ്ഥലത്തുനിന്ന് {m} മീ. ഉള്ളിൽ. അതിന് പുറത്തുള്ള പഞ്ചുകൾ അടയാളപ്പെടുത്തും.',
  'Start date': 'തുടങ്ങുന്ന തീയതി',
  'Start {date}': 'തുടക്കം {date}',
  'The due date is before the start date.': 'അവസാന തീയതി തുടങ്ങുന്ന തീയതിക്ക് മുമ്പാണ്.',
  'When did {name} leave on {date}?': '{date}-ന് {name} എപ്പോഴാണ് പോയത്?',
  'When does work start?': 'ജോലി എപ്പോൾ തുടങ്ങും?',
  'When must it be finished?': 'എപ്പോഴേക്ക് തീർക്കണം?',
  'Work has stopped for now': 'ജോലി ഇപ്പോൾ നിർത്തിയിരിക്കുന്നു',
  'Work is going on at the site': 'സൈറ്റിൽ ജോലി നടക്കുന്നു',
  'done {date}': '{date}-ന് തീർന്നു',
  'due {date}': 'അവസാന തീയതി {date}',
  'not out yet': 'ഇതുവരെ പുറത്തിറങ്ങിയിട്ടില്ല',
  'out {time}': 'പുറത്ത് {time}',
  '{done} of {total} tasks done': '{total}-ൽ {done} ജോലികൾ തീർന്നു',
  '{n} days late': '{n} ദിവസം വൈകി',
  '{n} issues': '{n} പ്രശ്നങ്ങൾ',
  '{n}% complete': '{n}% പൂർത്തിയായി',
  'To do': 'ചെയ്യാനുള്ളത്',
  'Transport': 'ഗതാഗതം',
  'Equipment hire': 'ഉപകരണ വാടക',
  'Food & tea': 'ഭക്ഷണം & ചായ',
  'Other': 'മറ്റുള്ളവ',
  '1 day': '1 ദിവസം',
  '1 month': '1 മാസം',
  '1 week': '1 ആഴ്ച',
  '1 year': '1 വർഷം',
  '{n} months': '{n} മാസം',
  '{n} weeks': '{n} ആഴ്ച',
  '{n} years': '{n} വർഷം',
  'Access code': 'ആക്സസ് കോഡ്',
  'Approve it in your UPI or bank app. FieldOS opens by itself once {store} confirms the payment, usually within a few minutes.': 'നിങ്ങളുടെ ഇൻസ്റ്റന്റ് ട്രാൻസ്ഫർ അല്ലെങ്കിൽ ബാങ്ക് ആപ്പിൽ ഇത് അംഗീകരിക്കുക. {store} പേയ്മെന്റ് സ്ഥിരീകരിച്ചാൽ FieldOS സ്വയം തുറക്കും, സാധാരണ കുറച്ച് മിനിറ്റിനുള്ളിൽ.',
  'At least {n} characters': 'കുറഞ്ഞത് {n} അക്ഷരങ്ങൾ',
  'Check again': 'വീണ്ടും പരിശോധിക്കുക',
  'Choose a plan': 'ഒരു പ്ലാൻ തിരഞ്ഞെടുക്കുക',
  'Choose your plan': 'നിങ്ങളുടെ പ്ലാൻ തിരഞ്ഞെടുക്കുക',
  'Confirm your email first: open the link we sent you, then sign in here.': 'ആദ്യം നിങ്ങളുടെ ഇമെയിൽ സ്ഥിരീകരിക്കുക: ഞങ്ങൾ അയച്ച ലിങ്ക് തുറന്ന്, പിന്നെ ഇവിടെ സൈൻ ഇൻ ചെയ്യുക.',
  'Copy last report ({day})': 'കഴിഞ്ഞ റിപ്പോർട്ട് കോപ്പി ചെയ്യുക ({day})',
  'Could not check with {store} right now. Please try again in a minute.': 'ഇപ്പോൾ {store}-ൽ പരിശോധിക്കാൻ കഴിഞ്ഞില്ല. ഒരു മിനിറ്റ് കഴിഞ്ഞ് വീണ്ടും ശ്രമിക്കുക.',
  'Could not check your subscription with {store} right now. Please try again in a minute.': 'ഇപ്പോൾ {store}-ൽ നിങ്ങളുടെ സബ്സ്ക്രിപ്ഷൻ പരിശോധിക്കാൻ കഴിഞ്ഞില്ല. ഒരു മിനിറ്റ് കഴിഞ്ഞ് വീണ്ടും ശ്രമിക്കുക.',
  'Could not load the plans from {store}. Please try again, or send a bug report from the menu.': '{store}-ൽ നിന്ന് പ്ലാനുകൾ ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല. വീണ്ടും ശ്രമിക്കുക, അല്ലെങ്കിൽ മെനുവിൽ നിന്ന് ബഗ് റിപ്പോർട്ട് അയയ്ക്കുക.',
  'Could not open {store}. Open {path} yourself.': '{store} തുറക്കാൻ കഴിഞ്ഞില്ല. {path} നിങ്ങൾ തന്നെ തുറക്കുക.',
  'Download {language} translation?': '{language} പരിഭാഷ ഡൗൺലോഡ് ചെയ്യണോ?',
  'Enter access code': 'ആക്സസ് കോഡ് നൽകുക',
  'Every 3 months': 'ഓരോ 3 മാസത്തിലും',
  'Every 6 months': 'ഓരോ 6 മാസത്തിലും',
  'For example ravi, or your phone number': 'ഉദാഹരണത്തിന് ravi, അല്ലെങ്കിൽ നിങ്ങളുടെ ഫോൺ നമ്പർ',
  'Heard in {language} by Sarvam. Check the words before saving.': 'Sarvam {language}-ൽ കേട്ടത്. സേവ് ചെയ്യുന്നതിന് മുമ്പ് വാക്കുകൾ പരിശോധിക്കുക.',
  'Heard in {language} on this phone. Check the words before saving.': 'ഈ ഫോണിൽ {language}-ൽ കേട്ടത്. സേവ് ചെയ്യുന്നതിന് മുമ്പ് വാക്കുകൾ പരിശോധിക്കുക.',
  'Keep every site on track': 'എല്ലാ സൈറ്റുകളും കൃത്യമായി മുന്നോട്ട് കൊണ്ടുപോകുക',
  'Last synced: {last} · Waiting to send: {n}': 'അവസാനം സിങ്ക് ചെയ്തത്: {last} · അയയ്ക്കാൻ കാത്തിരിക്കുന്നത്: {n}',
  'Made in Hyderabad by {company}': '{company} ഹൈദരാബാദിൽ നിർമ്മിച്ചത്',
  'Manage or cancel': 'മാനേജ് ചെയ്യുക അല്ലെങ്കിൽ റദ്ദാക്കുക',
  'Monthly': 'മാസം തോറും',
  'Need help? {email}': 'സഹായം വേണോ? {email}',
  'New cloud accounts are switched off for now. Write to us at the support address and we will help.': 'പുതിയ ക്ലൗഡ് അക്കൗണ്ടുകൾ ഇപ്പോൾ നിർത്തിവച്ചിരിക്കുന്നു. സപ്പോർട്ട് വിലാസത്തിൽ ഞങ്ങൾക്ക് എഴുതുക, ഞങ്ങൾ സഹായിക്കാം.',
  'No FieldOS subscription was found on this {store} account.': 'ഈ {store} അക്കൗണ്ടിൽ FieldOS സബ്സ്ക്രിപ്ഷൻ ഒന്നും കണ്ടില്ല.',
  'No FieldOS subscription was found on this {store} account. If you subscribed with another account, switch to it in {store} and try again.': 'ഈ {store} അക്കൗണ്ടിൽ FieldOS സബ്സ്ക്രിപ്ഷൻ ഒന്നും കണ്ടില്ല. മറ്റൊരു അക്കൗണ്ട് വഴിയാണ് സബ്സ്ക്രൈബ് ചെയ്തതെങ്കിൽ, {store}-ൽ അതിലേക്ക് മാറി വീണ്ടും ശ്രമിക്കുക.',
  'No internet connection. Your work is saved on this phone; try again when you are online.': 'ഇന്റർനെറ്റ് കണക്ഷൻ ഇല്ല. നിങ്ങളുടെ ജോലി ഈ ഫോണിൽ സേവ് ചെയ്തിട്ടുണ്ട്; ഓൺലൈനിൽ ആകുമ്പോൾ വീണ്ടും ശ്രമിക്കുക.',
  'Not {name}? Log out': '{name} അല്ലേ? ലോഗ് ഔട്ട് ചെയ്യുക',
  'Only for people the FieldOS team gave a code to, such as app reviewers.': 'FieldOS ടീം കോഡ് നൽകിയവർക്ക് മാത്രം, ഉദാഹരണത്തിന് ആപ്പ് റിവ്യൂവർമാർക്ക്.',
  'Only the company owner can change roles.': 'കമ്പനി ഉടമയ്ക്ക് മാത്രമേ റോളുകൾ മാറ്റാൻ കഴിയൂ.',
  'Only the company owner can make a new join code.': 'കമ്പനി ഉടമയ്ക്ക് മാത്രമേ പുതിയ ജോയിൻ കോഡ് ഉണ്ടാക്കാൻ കഴിയൂ.',
  'Only the company owner can remove people from the team.': 'കമ്പനി ഉടമയ്ക്ക് മാത്രമേ ടീമിൽ നിന്ന് ആളുകളെ നീക്കം ചെയ്യാൻ കഴിയൂ.',
  'Payment waiting for approval': 'പേയ്മെന്റ് അംഗീകാരത്തിനായി കാത്തിരിക്കുന്നു',
  'Put {company} on the cloud': '{company} ക്ലൗഡിലേക്ക് മാറ്റുക',
  'Restore purchase': 'വാങ്ങിയത് തിരികെ കൊണ്ടുവരിക',
  'Sign in from Team & sync first.': 'ആദ്യം Team & sync-ൽ നിന്ന് സൈൻ ഇൻ ചെയ്യുക.',
  'Signed in as {email}': '{email} ആയി സൈൻ ഇൻ ചെയ്തിരിക്കുന്നു',
  'Something went wrong. Please try again, or send a bug report from the menu.': 'എന്തോ പിശക് സംഭവിച്ചു. വീണ്ടും ശ്രമിക്കുക, അല്ലെങ്കിൽ മെനുവിൽ നിന്ന് ബഗ് റിപ്പോർട്ട് അയയ്ക്കുക.',
  'Start {length} free trial': '{length} സൗജന്യ ട്രയൽ തുടങ്ങുക',
  'Still waiting for the payment. It can take a few minutes after you approve it.': 'പേയ്മെന്റിനായി ഇപ്പോഴും കാത്തിരിക്കുന്നു. നിങ്ങൾ അംഗീകരിച്ച ശേഷം കുറച്ച് മിനിറ്റ് എടുത്തേക്കാം.',
  'Subscribe for {price}': '{price}-ന് സബ്സ്ക്രൈബ് ചെയ്യുക',
  'Terms': 'നിബന്ധനകൾ',
  'That code is not right, or it is too old. Check it, or send a new code.': 'ആ കോഡ് ശരിയല്ല, അല്ലെങ്കിൽ അത് പഴയതാണ്. അത് പരിശോധിക്കുക, അല്ലെങ്കിൽ പുതിയ കോഡ് അയയ്ക്കുക.',
  'That email address cannot be used. Check it, or try another.': 'ആ ഇമെയിൽ വിലാസം ഉപയോഗിക്കാൻ കഴിയില്ല. അത് പരിശോധിക്കുക, അല്ലെങ്കിൽ മറ്റൊന്ന് നോക്കുക.',
  'That email already has a FieldOS cloud account. Sign in with its password.': 'ആ ഇമെയിലിന് ഇതിനകം FieldOS ക്ലൗഡ് അക്കൗണ്ട് ഉണ്ട്. അതിന്റെ പാസ്‌വേഡ് ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക.',
  'That email and password do not match. Check them and try again.': 'ആ ഇമെയിലും പാസ്‌വേഡും ചേരുന്നില്ല. അവ പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.',
  'That is already your password. Choose a different one, or sign in with it.': 'അത് ഇപ്പോൾത്തന്നെ നിങ്ങളുടെ പാസ്‌വേഡാണ്. വേറൊന്ന് തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ അതുപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക.',
  'That join code is not right. Check it with the person who shared it: it is 10 letters and numbers.': 'ആ ജോയിൻ കോഡ് ശരിയല്ല. അത് പങ്കിട്ട ആളോട് ചോദിച്ച് ഉറപ്പാക്കുക: അത് 10 അക്ഷരങ്ങളും അക്കങ്ങളുമാണ്.',
  'That took too long. Check your connection and try again.': 'വളരെ സമയമെടുത്തു. നിങ്ങളുടെ കണക്ഷൻ പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.',
  'The FieldOS cloud is not answering right now. Your work is saved on this phone; try again in a few minutes.': 'FieldOS ക്ലൗഡ് ഇപ്പോൾ മറുപടി നൽകുന്നില്ല. നിങ്ങളുടെ ജോലി ഈ ഫോണിൽ സേവ് ചെയ്തിട്ടുണ്ട്; കുറച്ച് മിനിറ്റ് കഴിഞ്ഞ് വീണ്ടും ശ്രമിക്കുക.',
  'The FieldOS team gave you this access, so there is nothing to pay or cancel. When it ends, FieldOS asks you to choose a plan, and your records stay on this phone.': 'ഈ ആക്സസ് FieldOS ടീം നൽകിയതാണ്, അതിനാൽ പണം അടയ്ക്കാനോ റദ്ദാക്കാനോ ഒന്നുമില്ല. ഇത് തീരുമ്പോൾ ഒരു പ്ലാൻ തിരഞ്ഞെടുക്കാൻ FieldOS ആവശ്യപ്പെടും, നിങ്ങളുടെ രേഖകൾ ഈ ഫോണിൽത്തന്നെ ഉണ്ടാകും.',
  'The company owner cannot be removed from the team.': 'കമ്പനി ഉടമയെ ടീമിൽ നിന്ന് നീക്കം ചെയ്യാൻ കഴിയില്ല.',
  'The purchase did not finish. Please try again.': 'വാങ്ങൽ പൂർത്തിയായില്ല. വീണ്ടും ശ്രമിക്കുക.',
  'The subscription is not on sale yet. Please try again later.': 'സബ്സ്ക്രിപ്ഷൻ ഇതുവരെ വിൽപനയ്ക്ക് വന്നിട്ടില്ല. പിന്നീട് വീണ്ടും ശ്രമിക്കുക.',
  'This company is already on the cloud under another account. Ask its owner for a join code.': 'ഈ കമ്പനി ഇതിനകം മറ്റൊരു അക്കൗണ്ടിൽ ക്ലൗഡിലുണ്ട്. അതിന്റെ ഉടമയോട് ജോയിൻ കോഡ് ചോദിക്കുക.',
  'This is a one-time download of about 30 MB. After that, {language} reports translate to English on this phone, with no internet and no cost.': 'ഇത് ഏകദേശം 30 MB-യുടെ ഒറ്റത്തവണ ഡൗൺലോഡാണ്. അതിനുശേഷം {language} റിപ്പോർട്ടുകൾ ഈ ഫോണിൽത്തന്നെ ഇംഗ്ലീഷിലേക്ക് പരിഭാഷപ്പെടുത്തും, ഇന്റർനെറ്റും ചെലവും ഇല്ലാതെ.',
  'To cancel, open {path}. You keep FieldOS Pro until the end of the period you have paid for, and your records stay on this phone.': 'റദ്ദാക്കാൻ {path} തുറക്കുക. പണം അടച്ച കാലയളവ് തീരുന്നതുവരെ FieldOS Pro നിങ്ങൾക്ക് ഉണ്ടാകും, നിങ്ങളുടെ രേഖകൾ ഈ ഫോണിൽത്തന്നെ ഉണ്ടാകും.',
  'Too many tries in a short time. Wait a few minutes, then try again.': 'കുറഞ്ഞ സമയത്തിനുള്ളിൽ വളരെയധികം ശ്രമങ്ങൾ. കുറച്ച് മിനിറ്റ് കാത്തിരുന്ന് വീണ്ടും ശ്രമിക്കുക.',
  'Too many wrong join codes. Wait an hour, then try again with the code from your company owner.': 'വളരെയധികം തെറ്റായ ജോയിൻ കോഡുകൾ. ഒരു മണിക്കൂർ കാത്തിരുന്ന്, കമ്പനി ഉടമയിൽ നിന്നുള്ള കോഡ് ഉപയോഗിച്ച് വീണ്ടും ശ്രമിക്കുക.',
  'Translated from {language} on this phone': 'ഈ ഫോണിൽ {language}-ൽ നിന്ന് പരിഭാഷപ്പെടുത്തിയത്',
  'Try it free for {length}': '{length} സൗജന്യമായി പരീക്ഷിക്കുക',
  'Unlock': 'അൺലോക്ക് ചെയ്യുക',
  'Update payment method': 'പേയ്മെന്റ് രീതി മാറ്റുക',
  'Versions — {name}': 'പതിപ്പുകൾ — {name}',
  'Weekly': 'ആഴ്ച തോറും',
  'Welcome to FieldOS': 'FieldOS-ലേക്ക് സ്വാഗതം',
  'Welcome, {name}': 'സ്വാഗതം, {name}',
  'Which day is this report for?': 'ഈ റിപ്പോർട്ട് ഏത് ദിവസത്തേതാണ്?',
  'Works out to {price} a month': 'മാസം {price} ആയി വരും',
  'Yearly': 'വർഷം തോറും',
  'You are the owner, so your own role stays the same.': 'നിങ്ങളാണ് ഉടമ, അതിനാൽ നിങ്ങളുടെ റോൾ മാറില്ല.',
  'Your cloud sign-in has ended. Sign in again from Team & sync.': 'നിങ്ങളുടെ ക്ലൗഡ് സൈൻ ഇൻ അവസാനിച്ചു. Team & sync-ൽ നിന്ന് വീണ്ടും സൈൻ ഇൻ ചെയ്യുക.',
  'Your plan': 'നിങ്ങളുടെ പ്ലാൻ',
  'This needs a FieldOS server update that is on its way. Your work is safe on the phone; try again in a day or two.': 'ഇതിന് വരാനിരിക്കുന്ന ഒരു FieldOS സെർവർ അപ്ഡേറ്റ് വേണം. നിങ്ങളുടെ ജോലി ഫോണിൽ സുരക്ഷിതമാണ്; ഒന്നോ രണ്ടോ ദിവസം കഴിഞ്ഞ് വീണ്ടും ശ്രമിക്കുക.',
  'Update FieldOS to keep syncing. Everything you enter is saved on this phone and goes up once you update.': 'സിങ്ക് തുടരാൻ FieldOS അപ്ഡേറ്റ് ചെയ്യുക. നിങ്ങൾ നൽകുന്നതെല്ലാം ഈ ഫോണിൽ സേവ് ചെയ്യും, അപ്ഡേറ്റ് ചെയ്താൽ ഉടൻ അപ്‌ലോഡ് ആകും.',
  'A newer FieldOS is needed': 'FieldOS-ന്റെ പുതിയ പതിപ്പ് വേണം',
  'Update now': 'ഇപ്പോൾ അപ്ഡേറ്റ് ചെയ്യുക',
  'Open the App Store and update FieldOS.': 'App Store തുറന്ന് FieldOS അപ്ഡേറ്റ് ചെയ്യുക.',
  'Block {name}': '{name}-നെ ബ്ലോക്ക് ചെയ്യുക',
  'Hide their chat messages on this phone': 'ഈ ഫോണിൽ അവരുടെ ചാറ്റ് സന്ദേശങ്ങൾ മറയ്ക്കുക',
  'Block {name}?': '{name}-നെ ബ്ലോക്ക് ചെയ്യണോ?',
  'Their chat messages will be hidden on this phone. They stay in the company, and their site records are not hidden. You can unblock them in Settings › Blocked people.': 'അവരുടെ ചാറ്റ് സന്ദേശങ്ങൾ ഈ ഫോണിൽ മറയ്ക്കും. അവർ കമ്പനിയിൽ തുടരും, അവരുടെ സൈറ്റ് രേഖകൾ മറയ്ക്കില്ല. Settings › Blocked people-ൽ അവരെ അൺബ്ലോക്ക് ചെയ്യാം.',
  'Block and report': 'ബ്ലോക്ക് ചെയ്ത് റിപ്പോർട്ട് ചെയ്യുക',
  'Block': 'ബ്ലോക്ക് ചെയ്യുക',
  '{name} is blocked on this phone.': '{name}-നെ ഈ ഫോണിൽ ബ്ലോക്ക് ചെയ്തു.',
  'Blocked people': 'ബ്ലോക്ക് ചെയ്തവർ',
  'Nobody is blocked. To block someone, press and hold one of their chat messages.': 'ആരെയും ബ്ലോക്ക് ചെയ്തിട്ടില്ല. ഒരാളെ ബ്ലോക്ക് ചെയ്യാൻ, അവരുടെ ഒരു ചാറ്റ് സന്ദേശത്തിൽ അമർത്തിപ്പിടിക്കുക.',
  'Their chat messages are hidden on this phone. They stay in the company, and their site records are not hidden.': 'അവരുടെ ചാറ്റ് സന്ദേശങ്ങൾ ഈ ഫോണിൽ മറച്ചിരിക്കുന്നു. അവർ കമ്പനിയിൽ തുടരും, അവരുടെ സൈറ്റ് രേഖകൾ മറയ്ക്കില്ല.',
  'Unblock': 'അൺബ്ലോക്ക് ചെയ്യുക',
  'People whose chat messages are hidden on this phone': 'ചാറ്റ് സന്ദേശങ്ങൾ ഈ ഫോണിൽ മറച്ചിട്ടുള്ളവർ',
  'Privacy': 'സ്വകാര്യത',
  'Send crash details': 'ക്രാഷ് വിവരങ്ങൾ അയയ്ക്കുക',
  'If FieldOS crashes, send the error to the FieldOS team so it gets fixed. No site data is sent.': 'FieldOS ക്രാഷ് ആയാൽ, അത് ശരിയാക്കാൻ പിശക് FieldOS ടീമിന് അയയ്ക്കുക. സൈറ്റ് ഡാറ്റ ഒന്നും അയയ്ക്കില്ല.',
  'Your role in this company does not allow that. Ask the owner.': 'ഈ കമ്പനിയിലെ നിങ്ങളുടെ റോളിന് അതിന് അനുമതിയില്ല. ഉടമയോട് ചോദിക്കുക.',
  'Your subscription is on this phone.': 'നിങ്ങളുടെ സബ്സ്ക്രിപ്ഷൻ ഈ ഫോണിലാണ്.',
  'and {n} more': 'കൂടാതെ {n} എണ്ണം',
  'every 3 months': 'ഓരോ 3 മാസത്തിലും',
  'every 6 months': 'ഓരോ 6 മാസത്തിലും',
  'every month': 'എല്ലാ മാസവും',
  'every week': 'എല്ലാ ആഴ്ചയും',
  'every year': 'എല്ലാ വർഷവും',
  'the original': 'ഒറിജിനൽ',
  '{amount} payable': '{amount} നൽകാനുണ്ട്',
  '{length} free': '{length} സൗജന്യം',
  '{length} free, then {price}. {store} charges you when the trial ends unless you cancel at least 24 hours before. It renews {renews} until you cancel in {cancelIn}.': '{length} സൗജന്യം, പിന്നെ {price}. ട്രയൽ തീരുന്നതിന് കുറഞ്ഞത് 24 മണിക്കൂർ മുമ്പ് റദ്ദാക്കിയില്ലെങ്കിൽ ട്രയൽ തീരുമ്പോൾ {store} പണം ഈടാക്കും. {cancelIn}-ൽ റദ്ദാക്കുന്നതുവരെ ഇത് {renews} പുതുക്കും.',
  '{name} placed here, with a 100 m attendance geofence.': '{name} ഇവിടെ സ്ഥാപിച്ചു, 100 മീ. ഹാജർ ജിയോഫെൻസോടെ.',
  '{n} changes could not be sent after several tries.': 'പല തവണ ശ്രമിച്ചിട്ടും {n} മാറ്റങ്ങൾ അയയ്ക്കാൻ കഴിഞ്ഞില്ല.',
  '{n} projects without a site location': 'സൈറ്റ് ലൊക്കേഷൻ ഇല്ലാത്ത {n} പ്രോജക്റ്റുകൾ',
  '{price} a month': 'മാസം {price}',
  '{price} a week': 'ആഴ്ചയിൽ {price}',
  '{price} a year': 'വർഷം {price}',
  '{price} every 3 months': 'ഓരോ 3 മാസത്തിലും {price}',
  '{price} every 6 months': 'ഓരോ 6 മാസത്തിലും {price}',
  '{price}, charged by {store} today. It renews {renews} until you cancel in {cancelIn}, at least 24 hours before the next payment.': '{price}, ഇന്ന് {store} ഈടാക്കും. അടുത്ത പേയ്മെന്റിന് കുറഞ്ഞത് 24 മണിക്കൂർ മുമ്പ് {cancelIn}-ൽ റദ്ദാക്കുന്നതുവരെ ഇത് {renews} പുതുക്കും.',
  'Earned {earned} · Paid {paid} · Still due {due}': 'സമ്പാദിച്ചത് {earned} · നൽകിയത് {paid} · ഇനി നൽകാനുള്ളത് {due}',
  '{n} day ({h} h)': '{n} ദിവസം ({h} മ.)',
  '{n} days ({h} h)': '{n} ദിവസം ({h} മ.)',
  'OT {h} h': 'ഓവർടൈം {h} മണിക്കൂർ',
  'no daily wage set': 'ദിവസ വേതനം സെറ്റ് ചെയ്തിട്ടില്ല',
  '{amount}/day': '{amount}/ദിവസം',
  '1 missing punch-out (half day)': '1 പഞ്ച്-ഔട്ട് ഇല്ല (അര ദിവസം)',
  '{n} missing punch-outs (half days)': '{n} പഞ്ച്-ഔട്ടുകൾ ഇല്ല (അര ദിവസങ്ങൾ)',
  'paid {amount}': '{amount} നൽകി',
  'advance': 'അഡ്വാൻസ്',
  'due': 'നൽകാനുള്ളത്',
  '{from} to {to}': '{from} മുതൽ {to} വരെ',
  'Your language': 'നിങ്ങളുടെ ഭാഷ',
  'Mitra talks with you in it, mixed with English, and voice input listens for it.': 'Mitra നിങ്ങളോട് ഈ ഭാഷയിൽ, ഇംഗ്ലീഷ് കലർത്തി സംസാരിക്കും, വോയ്സ് ഇൻപുട്ടും ഈ ഭാഷ കേൾക്കും.',
  'Show screens in {language}': 'സ്ക്രീനുകൾ {language}-ൽ കാണിക്കുക',
  'Off: screens stay in English. Mitra still talks in your language.': 'ഓഫ്: സ്ക്രീനുകൾ ഇംഗ്ലീഷിൽ തുടരും. Mitra എന്നിട്ടും നിങ്ങളുടെ ഭാഷയിൽ സംസാരിക്കും.',
  'Language and voice': 'ഭാഷയും വോയ്സും',
  'Show this week\'s expenses': 'ഈ ആഴ്ചത്തെ ചെലവുകൾ കാണിക്കുക',
  'What is due this week?': 'ഈ ആഴ്ച എന്തൊക്കെ നൽകാനുണ്ട്?',
  'Who was absent today?': 'ഇന്ന് ആരൊക്കെ ഹാജരായില്ല?',
  'How much did labour cost this week?': 'ഈ ആഴ്ച തൊഴിലാളികൾക്ക് എത്ര ചെലവായി?',
  'Any open issues on site?': 'സൈറ്റിൽ തീർപ്പാകാത്ത പ്രശ്നങ്ങൾ ഉണ്ടോ?',
  'Which materials are running low?': 'ഏതൊക്കെ മെറ്റീരിയലുകളാണ് തീരാറായത്?',
  'What needs my approval?': 'എന്റെ അംഗീകാരം വേണ്ടത് എന്തിനൊക്കെ?',
  'You might ask next': 'അടുത്തതായി നിങ്ങൾക്ക് ചോദിക്കാം',
  'Past chats': 'മുമ്പത്തെ ചാറ്റുകൾ',
  'Delete all': 'എല്ലാം ഡിലീറ്റ് ചെയ്യുക',
  'No earlier chats yet. Your chats are kept on this phone.': 'മുമ്പത്തെ ചാറ്റുകൾ ഒന്നുമില്ല. നിങ്ങളുടെ ചാറ്റുകൾ ഈ ഫോണിൽ സൂക്ഷിക്കും.',
  '1 open issue': '1 തീർപ്പാകാത്ത പ്രശ്നം',
  '{n} open issues': '{n} തീർപ്പാകാത്ത പ്രശ്നങ്ങൾ',
  '1 worker punched in': '1 തൊഴിലാളി പഞ്ച് ഇൻ ചെയ്തു',
  '{n} workers punched in': '{n} തൊഴിലാളികൾ പഞ്ച് ഇൻ ചെയ്തു',
  'A material receipt is waiting for a decision': 'ഒരു മെറ്റീരിയൽ രസീത് തീരുമാനത്തിനായി കാത്തിരിക്കുന്നു',
  'A purchase order is waiting for a decision': 'ഒരു LPO (പർച്ചേസ് ഓർഡർ) തീരുമാനത്തിനായി കാത്തിരിക്കുന്നു',
  'A request is waiting for a decision': 'ഒരു അഭ്യർത്ഥന തീരുമാനത്തിനായി കാത്തിരിക്കുന്നു',
  'A site over budget is waiting for a decision': 'ബജറ്റ് കവിഞ്ഞ ഒരു സൈറ്റ് തീരുമാനത്തിനായി കാത്തിരിക്കുന്നു',
  'A new code is on its way to {email}. Codes stop working after an hour.': 'പുതിയ കോഡ് {email}-ലേക്ക് അയയ്ക്കുന്നു. കോഡുകൾ ഒരു മണിക്കൂറിന് ശേഷം പ്രവർത്തിക്കില്ല.',
  'A project': 'ഒരു പ്രോജക്റ്റ്',
  'A purchase is already in progress. Wait for it to finish.': 'ഒരു വാങ്ങൽ ഇപ്പോൾ നടക്കുന്നുണ്ട്. അത് തീരുന്നതുവരെ കാത്തിരിക്കുക.',
  'Access codes are 10 or more letters and numbers. Type it exactly as you got it.': 'ആക്സസ് കോഡുകൾ 10-ഓ അതിലധികമോ അക്ഷരങ്ങളും അക്കങ്ങളുമാണ്. കിട്ടിയതുപോലെ കൃത്യമായി ടൈപ്പ് ചെയ്യുക.',
  'Account created for {email}.': '{email}-ന് അക്കൗണ്ട് ഉണ്ടാക്കി.',
  'Approval requested': 'അംഗീകാരം അഭ്യർത്ഥിച്ചു',
  'Choose a new password of at least 6 characters.': 'കുറഞ്ഞത് 6 അക്ഷരങ്ങളുള്ള പുതിയ പാസ്‌വേഡ് തിരഞ്ഞെടുക്കുക.',
  'Companies where you are the only member are deleted from the cloud with all their records. Companies with other members keep their records, and ownership passes to another member.': 'നിങ്ങൾ മാത്രം അംഗമായ കമ്പനികൾ അവയുടെ എല്ലാ രേഖകളോടും കൂടി ക്ലൗഡിൽ നിന്ന് ഡിലീറ്റ് ചെയ്യും. മറ്റ് അംഗങ്ങളുള്ള കമ്പനികളുടെ രേഖകൾ നിലനിൽക്കും, ഉടമസ്ഥാവകാശം മറ്റൊരു അംഗത്തിന് കൈമാറും.',
  'Could not sign in. Try again.': 'സൈൻ ഇൻ ചെയ്യാൻ കഴിഞ്ഞില്ല. വീണ്ടും ശ്രമിക്കുക.',
  'Data on this phone is not deleted. Uninstall the app to remove it.': 'ഈ ഫോണിലെ ഡാറ്റ ഡിലീറ്റ് ആകില്ല. അത് നീക്കാൻ ആപ്പ് അൺഇൻസ്റ്റാൾ ചെയ്യുക.',
  'Edit item': 'ഇനം എഡിറ്റ് ചെയ്യുക',
  'Enter the join code from your company owner.': 'കമ്പനി ഉടമ തന്ന ജോയിൻ കോഡ് നൽകുക.',
  'Enter your email and a password of at least 6 characters.': 'നിങ്ങളുടെ ഇമെയിലും കുറഞ്ഞത് 6 അക്ഷരങ്ങളുള്ള പാസ്‌വേഡും നൽകുക.',
  'Free access from the FieldOS team': 'FieldOS ടീമിൽ നിന്നുള്ള സൗജന്യ ആക്സസ്',
  'Free access from the FieldOS team until {date}': '{date} വരെ FieldOS ടീമിൽ നിന്നുള്ള സൗജന്യ ആക്സസ്',
  'Free trial (will not renew)': 'സൗജന്യ ട്രയൽ (പുതുക്കില്ല)',
  'Free trial until {date} (will not renew)': '{date} വരെ സൗജന്യ ട്രയൽ (പുതുക്കില്ല)',
  'Free trial until {date}, then paid': '{date} വരെ സൗജന്യ ട്രയൽ, പിന്നെ പണം നൽകണം',
  'Free trial, then paid': 'സൗജന്യ ട്രയൽ, പിന്നെ പണം നൽകണം',
  'Get the {language} speech pack to work offline': 'ഓഫ്‌ലൈനിൽ പ്രവർത്തിക്കാൻ {language} സ്പീച്ച് പാക്ക് എടുക്കുക',
  'Give the project a name, such as the site or building.': 'പ്രോജക്റ്റിന് ഒരു പേര് നൽകുക, ഉദാഹരണത്തിന് സൈറ്റിന്റെയോ കെട്ടിടത്തിന്റെയോ പേര്.',
  'Headcount not given': 'ആളുകളുടെ എണ്ണം നൽകിയിട്ടില്ല',
  'If {email} has an account, a code is on its way. Type it below with your new password.': '{email}-ന് അക്കൗണ്ട് ഉണ്ടെങ്കിൽ, ഒരു കോഡ് അയയ്ക്കുന്നുണ്ട്. അത് താഴെ നിങ്ങളുടെ പുതിയ പാസ്‌വേഡിനൊപ്പം ടൈപ്പ് ചെയ്യുക.',
  'Items': 'ഇനങ്ങൾ',
  'Join company': 'കമ്പനിയിൽ ചേരുക',
  'Joined {company}. Projects will appear after the first sync.': '{company}-ൽ ചേർന്നു. ആദ്യ സിങ്കിന് ശേഷം പ്രോജക്റ്റുകൾ കാണാം.',
  'Keep the names under 200 characters.': 'പേരുകൾ 200 അക്ഷരങ്ങളിൽ താഴെയാക്കുക.',
  'Listening stopped': 'കേൾക്കുന്നത് നിർത്തി',
  'Listening · {time}': 'കേൾക്കുന്നു · {time}',
  'Location is blocked for FieldOS. Allow it in Android settings.': 'FieldOS-ന് ലൊക്കേഷൻ ബ്ലോക്ക് ചെയ്തിരിക്കുന്നു. Android സെറ്റിംഗ്സിൽ അനുവദിക്കുക.',
  'Location is turned off. Turn on GPS and try again.': 'ലൊക്കേഷൻ ഓഫാണ്. GPS ഓണാക്കി വീണ്ടും ശ്രമിക്കുക.',
  'Location permission was not given.': 'ലൊക്കേഷൻ അനുമതി നൽകിയിട്ടില്ല.',
  'Mark as not paid': 'പണം നൽകിയിട്ടില്ല എന്ന് അടയാളപ്പെടുത്തുക',
  'Mark as paid': 'പണം നൽകി എന്ന് അടയാളപ്പെടുത്തുക',
  'Microphone is off for FieldOS': 'FieldOS-ന് മൈക്രോഫോൺ ഓഫാണ്',
  'New issue (critical)': 'പുതിയ പ്രശ്നം (ഗുരുതരം)',
  'New issue (high)': 'പുതിയ പ്രശ്നം (ഉയർന്നത്)',
  'New issue (low)': 'പുതിയ പ്രശ്നം (കുറഞ്ഞത്)',
  'New issue (medium)': 'പുതിയ പ്രശ്നം (ഇടത്തരം)',
  'New join code created. The old code no longer works.': 'പുതിയ ജോയിൻ കോഡ് ഉണ്ടാക്കി. പഴയ കോഡ് ഇനി പ്രവർത്തിക്കില്ല.',
  'New password saved. Signed in as {email}.': 'പുതിയ പാസ്‌വേഡ് സേവ് ചെയ്തു. {email} ആയി സൈൻ ഇൻ ചെയ്തു.',
  'No active subscription': 'സജീവ സബ്സ്ക്രിപ്ഷൻ ഇല്ല',
  'No internet connection. Connect and try again.': 'ഇന്റർനെറ്റ് കണക്ഷൻ ഇല്ല. കണക്ട് ചെയ്ത് വീണ്ടും ശ്രമിക്കുക.',
  'Not set': 'സെറ്റ് ചെയ്തിട്ടില്ല',
  'One project for each site. Its daily reports, labour, materials, money and photos stay together.': 'ഓരോ സൈറ്റിനും ഒരു പ്രോജക്റ്റ്. അതിന്റെ ദിവസ റിപ്പോർട്ടുകൾ, തൊഴിലാളികൾ, മെറ്റീരിയലുകൾ, പണം, ഫോട്ടോകൾ എല്ലാം ഒരുമിച്ച് ഉണ്ടാകും.',
  'Payment problem: update your payment method in the store': 'പേയ്മെന്റ് പ്രശ്നം: സ്റ്റോറിൽ നിങ്ങളുടെ പേയ്മെന്റ് രീതി മാറ്റുക',
  'Payment problem: update your payment method in the store before {date}': 'പേയ്മെന്റ് പ്രശ്നം: {date}-ന് മുമ്പ് സ്റ്റോറിൽ നിങ്ങളുടെ പേയ്മെന്റ് രീതി മാറ്റുക',
  'Photo is on the phone that took it': 'ഫോട്ടോ അത് എടുത്ത ഫോണിലാണ്',
  'Pick a time after they punched in ({time}).': 'അവർ പഞ്ച് ഇൻ ചെയ്തതിന് ശേഷമുള്ള ഒരു സമയം തിരഞ്ഞെടുക്കുക ({time}).',
  'Put company on the cloud': 'കമ്പനി ക്ലൗഡിലേക്ക് മാറ്റുക',
  'Quantity this bill': 'ഈ ബില്ലിലെ അളവ്',
  'Recording · {time} · tap to stop and send': 'റെക്കോർഡ് ചെയ്യുന്നു · {time} · നിർത്തി അയയ്ക്കാൻ ടാപ്പ് ചെയ്യുക',
  'Sign in': 'സൈൻ ഇൻ',
  'Signed in as {email}.': '{email} ആയി സൈൻ ഇൻ ചെയ്തു.',
  'Signed out. This phone keeps working offline.': 'സൈൻ ഔട്ട് ചെയ്തു. ഈ ഫോൺ ഓഫ്‌ലൈനിൽ പ്രവർത്തിക്കുന്നത് തുടരും.',
  'Subscribed': 'സബ്സ്ക്രൈബ് ചെയ്തു',
  'Subscribed until {date} (cancelled)': '{date} വരെ സബ്സ്ക്രൈബ് ചെയ്തു (റദ്ദാക്കി)',
  'Subscribed, renews on {date}': 'സബ്സ്ക്രൈബ് ചെയ്തു, {date}-ന് പുതുക്കും',
  'Sync now': 'ഇപ്പോൾ സിങ്ക് ചെയ്യുക',
  'Synced. 1 change sent, latest data received.': 'സിങ്ക് ചെയ്തു. 1 മാറ്റം അയച്ചു, പുതിയ ഡാറ്റ ലഭിച്ചു.',
  'Synced. {n} changes sent, latest data received.': 'സിങ്ക് ചെയ്തു. {n} മാറ്റങ്ങൾ അയച്ചു, പുതിയ ഡാറ്റ ലഭിച്ചു.',
  'Tap the mic and speak': 'മൈക്കിൽ ടാപ്പ് ചെയ്ത് സംസാരിക്കുക',
  'Tap to start recording': 'റെക്കോർഡിംഗ് തുടങ്ങാൻ ടാപ്പ് ചെയ്യുക',
  'That code is not valid or has ended. Check it and try again, or ask whoever gave it to you.': 'ആ കോഡ് സാധുവല്ല, അല്ലെങ്കിൽ കാലാവധി കഴിഞ്ഞു. പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക, അല്ലെങ്കിൽ തന്ന ആളോട് ചോദിക്കുക.',
  'That plan is no longer on sale. Please pick again.': 'ആ പ്ലാൻ ഇപ്പോൾ വിൽപനയിലില്ല. വീണ്ടും തിരഞ്ഞെടുക്കുക.',
  'The FieldOS plans are not on sale in {store} yet. Please try again later, or send a bug report from the menu.': 'FieldOS പ്ലാനുകൾ {store}-ൽ ഇതുവരെ വിൽപനയ്ക്ക് വന്നിട്ടില്ല. പിന്നീട് വീണ്ടും ശ്രമിക്കുക, അല്ലെങ്കിൽ മെനുവിൽ നിന്ന് ബഗ് റിപ്പോർട്ട് അയയ്ക്കുക.',
  'The owner or a project manager decides these. You can see what is waiting.': 'ഉടമയോ പ്രോജക്റ്റ് മാനേജരോ ആണ് ഇവ തീരുമാനിക്കുന്നത്. കാത്തിരിക്കുന്നത് എന്തൊക്കെയെന്ന് നിങ്ങൾക്ക് കാണാം.',
  'The phone stopped listening. Tap Try again, or type the report.': 'ഫോൺ കേൾക്കുന്നത് നിർത്തി. വീണ്ടും ശ്രമിക്കുക ടാപ്പ് ചെയ്യുക, അല്ലെങ്കിൽ റിപ്പോർട്ട് ടൈപ്പ് ചെയ്യുക.',
  'There is no internet, and the offline speech pack for {language} is not on this phone yet. Connect once, then download it: Google app › Settings › Voice › Offline speech recognition › {englishName}. After that, voice reports work anywhere on site.': 'ഇന്റർനെറ്റ് ഇല്ല, {language}-നുള്ള ഓഫ്‌ലൈൻ സ്പീച്ച് പാക്ക് ഈ ഫോണിൽ ഇതുവരെ ഇല്ല. ഒരിക്കൽ കണക്ട് ചെയ്ത് അത് ഡൗൺലോഡ് ചെയ്യുക: Google app › Settings › Voice › Offline speech recognition › {englishName}. അതിനുശേഷം സൈറ്റിൽ എവിടെയും വോയ്സ് റിപ്പോർട്ടുകൾ പ്രവർത്തിക്കും.',
  'This iPhone needs internet to recognise {language} speech. Connect and try again, or type the report.': '{language} സംസാരം തിരിച്ചറിയാൻ ഈ iPhone-ന് ഇന്റർനെറ്റ് വേണം. കണക്ട് ചെയ്ത് വീണ്ടും ശ്രമിക്കുക, അല്ലെങ്കിൽ റിപ്പോർട്ട് ടൈപ്പ് ചെയ്യുക.',
  'This needs internet for {language}': '{language}-ന് ഇന്റർനെറ്റ് വേണം',
  'This permanently deletes {email} from FieldOS cloud.': 'ഇത് FieldOS ക്ലൗഡിൽ നിന്ന് {email} സ്ഥിരമായി ഡിലീറ്റ് ചെയ്യും.',
  'This phone can\'t do {language} yet': 'ഈ ഫോണിൽ ഇതുവരെ {language} ലഭ്യമല്ല',
  'This phone can\'t turn {language} speech into text itself, so FieldOS will record you and send the recording to Sarvam when you stop. This needs internet.': 'ഈ ഫോണിന് {language} സംസാരം സ്വയം ടെക്സ്റ്റ് ആക്കാൻ കഴിയില്ല, അതിനാൽ FieldOS നിങ്ങളുടെ ശബ്ദം റെക്കോർഡ് ചെയ്ത്, നിങ്ങൾ നിർത്തുമ്പോൾ Sarvam-ലേക്ക് അയയ്ക്കും. ഇതിന് ഇന്റർനെറ്റ് വേണം.',
  'This phone has no speech recognition': 'ഈ ഫോണിൽ സ്പീച്ച് റെക്കഗ്നിഷൻ ഇല്ല',
  'This phone is not allowed to make purchases. Check the payment settings or parental controls in {store}.': 'ഈ ഫോണിൽ നിന്ന് വാങ്ങലുകൾ അനുവദിച്ചിട്ടില്ല. {store}-ലെ പേയ്മെന്റ് സെറ്റിംഗ്സ് അല്ലെങ്കിൽ പാരന്റൽ കൺട്രോൾസ് പരിശോധിക്കുക.',
  'This plan is not on sale in your country right now.': 'ഈ പ്ലാൻ ഇപ്പോൾ നിങ്ങളുടെ രാജ്യത്ത് വിൽപനയിലില്ല.',
  'This {store} account already pays for FieldOS for someone else. Write to us and we will sort it out.': 'ഈ {store} അക്കൗണ്ട് ഇതിനകം മറ്റൊരാൾക്കായി FieldOS-ന് പണം നൽകുന്നുണ്ട്. ഞങ്ങൾക്ക് എഴുതുക, ഞങ്ങൾ ശരിയാക്കാം.',
  'Turning your recording into text…': 'നിങ്ങളുടെ റെക്കോർഡിംഗ് ടെക്സ്റ്റ് ആക്കുന്നു…',
  'Turning your recording into text… {n} of {total}': 'നിങ്ങളുടെ റെക്കോർഡിംഗ് ടെക്സ്റ്റ് ആക്കുന്നു… {total}-ൽ {n}',
  'Type the code from the email: it is 6 digits.': 'ഇമെയിലിലെ കോഡ് ടൈപ്പ് ചെയ്യുക: അത് 6 അക്കങ്ങളാണ്.',
  'Type the code we emailed to {email}, and the new password for your cloud account.': 'ഞങ്ങൾ {email}-ലേക്ക് ഇമെയിൽ ചെയ്ത കോഡും നിങ്ങളുടെ ക്ലൗഡ് അക്കൗണ്ടിന്റെ പുതിയ പാസ്‌വേഡും ടൈപ്പ് ചെയ്യുക.',
  'Type the code we emailed to {email}. It can take a minute to arrive; look in spam too.': 'ഞങ്ങൾ {email}-ലേക്ക് ഇമെയിൽ ചെയ്ത കോഡ് ടൈപ്പ് ചെയ്യുക. എത്താൻ ഒരു മിനിറ്റ് എടുത്തേക്കാം; സ്പാമിലും നോക്കുക.',
  'Type your email above first, then tap "Forgot password?" again.': 'ആദ്യം മുകളിൽ നിങ്ങളുടെ ഇമെയിൽ ടൈപ്പ് ചെയ്യുക, പിന്നെ വീണ്ടും "പാസ്‌വേഡ് മറന്നോ?" ടാപ്പ് ചെയ്യുക.',
  'We sent a code to {email}. Type it below to finish creating your account.': 'ഞങ്ങൾ {email}-ലേക്ക് ഒരു കോഡ് അയച്ചു. അക്കൗണ്ട് ഉണ്ടാക്കൽ പൂർത്തിയാക്കാൻ അത് താഴെ ടൈപ്പ് ചെയ്യുക.',
  'Work measured this bill': 'ഈ ബില്ലിൽ അളന്ന ജോലി',
  'Working for someone else\'s company?': 'മറ്റൊരാളുടെ കമ്പനിക്കായി ജോലി ചെയ്യുന്നുണ്ടോ?',
  'Your cloud account is deleted. This phone keeps working offline.': 'നിങ്ങളുടെ ക്ലൗഡ് അക്കൗണ്ട് ഡിലീറ്റ് ചെയ്തു. ഈ ഫോൺ ഓഫ്‌ലൈനിൽ പ്രവർത്തിക്കുന്നത് തുടരും.',
  'Your payment is waiting for approval, for example in your UPI app. FieldOS opens by itself once {store} confirms it.': 'നിങ്ങളുടെ പേയ്മെന്റ് അംഗീകാരത്തിനായി കാത്തിരിക്കുന്നു, ഉദാഹരണത്തിന് നിങ്ങളുടെ ഇൻസ്റ്റന്റ് ട്രാൻസ്ഫർ ആപ്പിൽ. {store} സ്ഥിരീകരിച്ചാൽ FieldOS സ്വയം തുറക്കും.',
  'about {amount}': 'ഏകദേശം {amount}',
  'never': 'ഒരിക്കലുമില്ല',
