  '{company} is on the cloud. Share the join code with your team.': '{company} ക്ലൗഡിലാണ്. ജോയിൻ കോഡ് നിങ്ങളുടെ ടീമുമായി പങ്കിടുക.',
  '{day}, marked {mark}': '{day}, {mark} എന്ന് അടയാളപ്പെടുത്തി',
  '{day}, {h} h': '{day}, {h} മ.',
  '{day}, {h} h, no punch-out': '{day}, {h} മ., പഞ്ച്-ഔട്ട് ഇല്ല',
  '{email} already has an account, and that password is not right for it. Try again, or tap "Forgot password?" to choose a new one.': '{email}-ന് ഇതിനകം അക്കൗണ്ട് ഉണ്ട്, ആ പാസ്‌വേഡ് അതിന് ശരിയല്ല. വീണ്ടും ശ്രമിക്കുക, അല്ലെങ്കിൽ പുതിയത് തിരഞ്ഞെടുക്കാൻ "പാസ്‌വേഡ് മറന്നോ?" ടാപ്പ് ചെയ്യുക.',
  '{email} is no longer on the team.': '{email} ഇനി ടീമിലില്ല.',
  '{email} will stop getting this company\'s projects and cannot send anything new. Work they already recorded stays.': '{email}-ന് ഇനി ഈ കമ്പനിയുടെ പ്രോജക്റ്റുകൾ കിട്ടില്ല, പുതിയതൊന്നും അയയ്ക്കാനും കഴിയില്ല. അവർ ഇതിനകം രേഖപ്പെടുത്തിയ ജോലി നിലനിൽക്കും.',
