  '{name}: out at {time} on {date}': '{name}: {date}-ന് {time}-ന് പുറത്ത്',
  '{n} new updates from your team': 'നിങ്ങളുടെ ടീമിൽ നിന്ന് {n} പുതിയ അപ്ഡേറ്റുകൾ',
  '{sent} sent, {waiting} waiting. They will retry on the next sync.': '{sent} അയച്ചു, {waiting} കാത്തിരിക്കുന്നു. അടുത്ത സിങ്കിൽ വീണ്ടും ശ്രമിക്കും.',
  '{store} could not complete that. Please try again, or send a bug report from the menu.': '{store}-ന് അത് പൂർത്തിയാക്കാൻ കഴിഞ്ഞില്ല. വീണ്ടും ശ്രമിക്കുക, അല്ലെങ്കിൽ മെനുവിൽ നിന്ന് ബഗ് റിപ്പോർട്ട് അയയ്ക്കുക.',
  '{store} had a problem with that. Please try again in a minute.': '{store}-ൽ അതിന് ഒരു പ്രശ്നമുണ്ടായി. ഒരു മിനിറ്റ് കഴിഞ്ഞ് വീണ്ടും ശ്രമിക്കുക.',
  '{store} is having a problem right now. Please try again in a minute.': '{store}-ന് ഇപ്പോൾ ഒരു പ്രശ്നമുണ്ട്. ഒരു മിനിറ്റ് കഴിഞ്ഞ് വീണ്ടും ശ്രമിക്കുക.',
  'Speak daily reports in your own language': 'ദിവസ റിപ്പോർട്ടുകൾ നിങ്ങളുടെ സ്വന്തം ഭാഷയിൽ പറയുക',
