  'Can see the site, changes nothing.': 'സൈറ്റ് കാണാം, ഒന്നും മാറ്റില്ല.',
  'Copies the set-up only. Nothing that happened on that site comes across.': 'സെറ്റപ്പ് മാത്രം കോപ്പി ചെയ്യും. ആ സൈറ്റിൽ നടന്ന ഒന്നും കൂടെ വരില്ല.',
