  'Estimate items and rates': 'എസ്റ്റിമേറ്റ് ഇനങ്ങളും നിരക്കുകളും',
  'Everyone in the company is already on this site.': 'കമ്പനിയിലെ എല്ലാവരും ഇതിനകം ഈ സൈറ്റിലുണ്ട്.',
  'Everyone in the company sees this site.': 'കമ്പനിയിലെ എല്ലാവർക്കും ഈ സൈറ്റ് കാണാം.',
  'Everyone in the company works here with their company role. Add people to give them a site role or an approval limit.': 'കമ്പനിയിലെ എല്ലാവരും അവരുടെ കമ്പനി റോളോടെ ഇവിടെ ജോലി ചെയ്യുന്നു. സൈറ്റ് റോളോ അംഗീകാര പരിധിയോ നൽകാൻ ആളുകളെ ചേർക്കുക.',
  'Everything on this site.': 'ഈ സൈറ്റിലെ എല്ലാം.',
  'Hidden from the rest of the company. The company\'s owners and managers still see it.': 'കമ്പനിയിലെ മറ്റുള്ളവരിൽ നിന്ന് മറച്ചിരിക്കുന്നു. കമ്പനിയുടെ ഉടമകൾക്കും മാനേജർമാർക്കും എന്നിട്ടും കാണാം.',
  'In the weekly close they approve items up to this. Leave empty for no limit.': 'ആഴ്ചതോറുമുള്ള ക്ലോസിൽ ഇത്രയും വരെയുള്ള ഇനങ്ങൾ അവർ അംഗീകരിക്കും. പരിധി വേണ്ടെങ്കിൽ ശൂന്യമായി വിടുക.',
