  'No supplier names found. Put one supplier on each line.': 'സപ്ലയർ പേരുകൾ ഒന്നും കണ്ടില്ല. ഓരോ വരിയിലും ഒരു സപ്ലയർ നൽകുക.',
  'On this site': 'ഈ സൈറ്റിൽ',
