  'Quantity measured': 'അളന്ന അളവ്',
  'Record the payment in the money book first. Every payment so far is already against a bill.': 'ആദ്യം പണ പുസ്തകത്തിൽ പേയ്മെന്റ് രേഖപ്പെടുത്തുക. ഇതുവരെയുള്ള എല്ലാ പേയ്മെന്റുകളും ഇതിനകം ഏതെങ്കിലും ബില്ലിലേക്ക് ചേർത്തിട്ടുണ്ട്.',
