  '{amount} still due': '{amount} ഇനിയും നൽകാനുണ്ട്',
  '{m} of {n} invoices need checking before payment.': 'പണം നൽകുന്നതിന് മുമ്പ് {n}-ൽ {m} ഇൻവോയ്സുകൾ പരിശോധിക്കണം.',
  '{n} amounts put against bills.': '{n} തുകകൾ ബില്ലുകളിലേക്ക് ചേർത്തു.',
  '{n} waiting for approval': '{n} അംഗീകാരത്തിനായി കാത്തിരിക്കുന്നു',
  '{paid} received, {due} due': '{paid} ലഭിച്ചു, {due} കിട്ടാനുണ്ട്',
  'All records, photos and bills in one file. Keep it on Drive or a computer.': 'എല്ലാ രേഖകളും ഫോട്ടോകളും ബില്ലുകളും ഒരു ഫയലിൽ. അത് Drive-ലോ കമ്പ്യൂട്ടറിലോ സൂക്ഷിക്കുക.',
  'Back up this phone': 'ഈ ഫോൺ ബാക്കപ്പ് ചെയ്യുക',
  'Backup checked': 'ബാക്കപ്പ് പരിശോധിച്ചു',
  'Backup failed: {error}': 'ബാക്കപ്പ് പരാജയപ്പെട്ടു: {error}',
  'Checked before anything is replaced': 'എന്തെങ്കിലും മാറ്റുന്നതിന് മുമ്പ് പരിശോധിക്കും',
  'Choose backup file': 'ബാക്കപ്പ് ഫയൽ തിരഞ്ഞെടുക്കുക',
  'Everything on this phone is replaced by the backup the next time FieldOS opens. The current data is kept aside on the phone in case you need it back.': 'അടുത്ത തവണ FieldOS തുറക്കുമ്പോൾ ഈ ഫോണിലുള്ളതെല്ലാം ബാക്കപ്പ് ഉപയോഗിച്ച് മാറ്റും. ഇപ്പോഴത്തെ ഡാറ്റ ആവശ്യമെങ്കിൽ തിരികെ എടുക്കാൻ ഫോണിൽ മാറ്റിവയ്ക്കും.',
  'FieldOS backup: {sites} sites, {files} photos and bills': 'FieldOS ബാക്കപ്പ്: {sites} സൈറ്റുകൾ, {files} ഫോട്ടോകളും ബില്ലുകളും',
  'Made {date}: {sites} sites, {files} photos and bills. Close FieldOS fully and open it again to finish the restore.': '{date}-ന് ഉണ്ടാക്കിയത്: {sites} സൈറ്റുകൾ, {files} ഫോട്ടോകളും ബില്ലുകളും. റീസ്റ്റോർ പൂർത്തിയാക്കാൻ FieldOS പൂർണ്ണമായി അടച്ച് വീണ്ടും തുറക്കുക.',
  'Restore a backup': 'ഒരു ബാക്കപ്പ് റീസ്റ്റോർ ചെയ്യുക',
  'Restore a backup?': 'ഒരു ബാക്കപ്പ് റീസ്റ്റോർ ചെയ്യണോ?',
  'Restore failed: {error}': 'റീസ്റ്റോർ പരാജയപ്പെട്ടു: {error}',
  'The backup is damaged and was not restored.': 'ബാക്കപ്പ് കേടാണ്, റീസ്റ്റോർ ചെയ്തില്ല.',
  'The backup is incomplete and was not restored.': 'ബാക്കപ്പ് അപൂർണ്ണമാണ്, റീസ്റ്റോർ ചെയ്തില്ല.',
  'This backup was made by a newer FieldOS. Update the app first.': 'ഈ ബാക്കപ്പ് FieldOS-ന്റെ പുതിയ പതിപ്പിൽ ഉണ്ടാക്കിയതാണ്. ആദ്യം ആപ്പ് അപ്ഡേറ്റ് ചെയ്യുക.',
  'This is not a FieldOS backup file.': 'ഇത് ഒരു FieldOS ബാക്കപ്പ് ഫയൽ അല്ല.',
  'The export did not pass its check, so it was not sent: {why}': 'എക്സ്പോർട്ട് പരിശോധനയിൽ പാസായില്ല, അതിനാൽ അയച്ചില്ല: {why}',
  'Above these amounts, a project manager approves first, then the owner. Leave a box blank for no approval. Rules cover what is recorded from now on.': 'ഈ തുകകൾക്ക് മുകളിൽ, ആദ്യം പ്രോജക്റ്റ് മാനേജരും പിന്നെ ഉടമയും അംഗീകരിക്കും. അംഗീകാരം വേണ്ടെങ്കിൽ ബോക്സ് ശൂന്യമായി വിടുക. ഇനിമുതൽ രേഖപ്പെടുത്തുന്നവയ്ക്കാണ് നിയമങ്ങൾ ബാധകം.',
  'Above what amount a project manager, then you, approve requests, expenses and orders': 'ഏത് തുകയ്ക്ക് മുകളിലാണ് പ്രോജക്റ്റ് മാനേജരും പിന്നെ നിങ്ങളും അഭ്യർത്ഥനകൾ, ചെലവുകൾ, ഓർഡറുകൾ അംഗീകരിക്കേണ്ടത്',
  'Approval rules': 'അംഗീകാര നിയമങ്ങൾ',
  'Approval rules saved': 'അംഗീകാര നിയമങ്ങൾ സേവ് ചെയ്തു',
  'Enter amounts in rupees, or leave blank.': 'തുകകൾ ദിർഹത്തിൽ നൽകുക, അല്ലെങ്കിൽ ശൂന്യമായി വിടുക.',
  'Note (needed to reject)': 'കുറിപ്പ് (നിരസിക്കാൻ ആവശ്യം)',
  'Owner also approves above (₹)': 'ഇതിന് മുകളിൽ ഉടമയും അംഗീകരിക്കും (₹)',
  'Project manager approves above (₹)': 'ഇതിന് മുകളിൽ പ്രോജക്റ്റ് മാനേജർ അംഗീകരിക്കും (₹)',
  'Purchase orders': 'LPO-കൾ',
  'Purchase requests': 'മെറ്റീരിയൽ അഭ്യർത്ഥനകൾ',
  'Purchase requests, orders and expenses above your approval amounts wait here.': 'നിങ്ങളുടെ അംഗീകാര തുകകൾക്ക് മുകളിലുള്ള മെറ്റീരിയൽ അഭ്യർത്ഥനകൾ, ഓർഡറുകൾ, ചെലവുകൾ ഇവിടെ കാത്തിരിക്കും.',
  'Say why it is rejected.': 'എന്തുകൊണ്ട് നിരസിക്കുന്നു എന്ന് പറയുക.',
  'Signed. It now waits for the owner\'s approval.': 'ഒപ്പിട്ടു. ഇനി ഉടമയുടെ അംഗീകാരത്തിനായി കാത്തിരിക്കുന്നു.',
  'The owner approves it after you.': 'നിങ്ങൾക്ക് ശേഷം ഉടമ ഇത് അംഗീകരിക്കും.',
  'The owner\'s amount should not be below the project manager\'s.': 'ഉടമയുടെ തുക പ്രോജക്റ്റ് മാനേജറുടേതിനെക്കാൾ കുറവാകരുത്.',
  'Waiting for a project manager\'s approval': 'പ്രോജക്റ്റ് മാനേജറുടെ അംഗീകാരത്തിനായി കാത്തിരിക്കുന്നു',
  'Waiting for the owner\'s approval': 'ഉടമയുടെ അംഗീകാരത്തിനായി കാത്തിരിക്കുന്നു',
  'Waiting for your approval': 'നിങ്ങളുടെ അംഗീകാരത്തിനായി കാത്തിരിക്കുന്നു',
  '{amount}. You sign as {level}.': '{amount}. നിങ്ങൾ {level} ആയി ഒപ്പിടുന്നു.',
  '{n} requests, orders or expenses above your approval amounts': 'നിങ്ങളുടെ അംഗീകാര തുകകൾക്ക് മുകളിലുള്ള {n} അഭ്യർത്ഥനകൾ, ഓർഡറുകൾ അല്ലെങ്കിൽ ചെലവുകൾ',
  'Audit trail': 'ഓഡിറ്റ് ട്രെയിൽ',
  'Every approval, cancellation and payment, who did it and when, in one file': 'എല്ലാ അംഗീകാരങ്ങളും റദ്ദാക്കലുകളും പേയ്മെന്റുകളും, ആര് എപ്പോൾ ചെയ്തു എന്നതടക്കം, ഒരു ഫയലിൽ',
  'Nothing has been recorded yet.': 'ഇതുവരെ ഒന്നും രേഖപ്പെടുത്തിയിട്ടില്ല.',
  'A decision cannot be changed afterwards.': 'ഒരു തീരുമാനം പിന്നീട് മാറ്റാൻ കഴിയില്ല.',
  'A work order is what you agreed with a subcontractor: the work, the quantity and the rate. Claims and certificates are checked against it.': 'ഒരു സബ്കോൺട്രാക്ടറുമായി നിങ്ങൾ സമ്മതിച്ചതാണ് സബ്കോൺട്രാക്ട് ഓർഡർ: ജോലി, അളവ്, നിരക്ക്. ക്ലെയിമുകളും സർട്ടിഫിക്കറ്റുകളും അതുമായി ഒത്തുനോക്കും.',
  'Accepted': 'സ്വീകരിച്ചു',
  'Access for {name}': '{name}-നുള്ള ആക്സസ്',
  'Actual cost': 'യഥാർത്ഥ ചെലവ്',
  'Add a photo of the work': 'ജോലിയുടെ ഒരു ഫോട്ടോ ചേർക്കുക',
  'Add another photo': 'മറ്റൊരു ഫോട്ടോ ചേർക്കുക',
  'Add budget lines (cost codes) with their original budget. Work orders, purchase orders and expenses put on a line show what is committed, what is spent and what the line will cost to finish.': 'ബജറ്റ് ലൈനുകൾ (കോസ്റ്റ് കോഡുകൾ) അവയുടെ യഥാർത്ഥ ബജറ്റോടെ ചേർക്കുക. ഒരു ലൈനിലേക്ക് ചേർക്കുന്ന സബ്കോൺട്രാക്ട് ഓർഡറുകൾ, LPO-കൾ, ചെലവുകൾ എന്നിവ എത്ര കമ്മിറ്റ് ചെയ്തു, എത്ര ചെലവായി, ലൈൻ തീർക്കാൻ എത്ര വരും എന്ന് കാണിക്കും.',
  'Add evidence photo': 'തെളിവ് ഫോട്ടോ ചേർക്കുക',
  'Add the subcontractor first, from Home > Subcontractors.': 'ആദ്യം Home > Subcontractors-ൽ നിന്ന് സബ്കോൺട്രാക്ടറെ ചേർക്കുക.',
  'Agreed': 'സമ്മതിച്ചത്',
  'Agreed (baseline)': 'സമ്മതിച്ചത് (ബേസ്‌ലൈൻ)',
  'Agreed quantity': 'സമ്മതിച്ച അളവ്',
  'Agreed {base}, plus {extra} by approved variations': 'സമ്മതിച്ചത് {base}, കൂടാതെ അംഗീകരിച്ച വേരിയേഷനുകൾ വഴി {extra}',
  'Approve variation': 'വേരിയേഷൻ അംഗീകരിക്കുക',
  'Approved amount': 'അംഗീകരിച്ച തുക',
  'Approved changes': 'അംഗീകരിച്ച മാറ്റങ്ങൾ',
  'Approved quantity': 'അംഗീകരിച്ച അളവ്',
  'Approved variations': 'അംഗീകരിച്ച വേരിയേഷനുകൾ',
