  'Budget (with approved changes)': 'ബജറ്റ് (അംഗീകരിച്ച മാറ്റങ്ങൾ ഉൾപ്പെടെ)',
  'Budget line': 'ബജറ്റ് ലൈൻ',
  'Certification overdue': 'സർട്ടിഫിക്കേഷൻ വൈകി',
  'Certified': 'സർട്ടിഫൈ ചെയ്തു',
  'Certified by the site': 'സൈറ്റ് സർട്ടിഫൈ ചെയ്തത്',
