  'Waiting in variations': 'വേരിയേഷനുകളിൽ കാത്തിരിക്കുന്നു',
  'We sent a code to {email}. Type it below, then tap Join.': 'ഞങ്ങൾ {email}-ലേക്ക് ഒരു കോഡ് അയച്ചു. അത് താഴെ ടൈപ്പ് ചെയ്ത്, ചേരുക ടാപ്പ് ചെയ്യുക.',
