  'When the builder gives your firm a work order, it appears here after a sync. Then you can claim the work you finish.': 'ബിൽഡർ നിങ്ങളുടെ സ്ഥാപനത്തിന് സബ്കോൺട്രാക്ട് ഓർഡർ നൽകുമ്പോൾ, സിങ്കിന് ശേഷം അത് ഇവിടെ കാണാം. പിന്നെ നിങ്ങൾ തീർക്കുന്ന ജോലി ക്ലെയിം ചെയ്യാം.',
