  '{name}: install FieldOS, tap "Subcontractor? Join free with the builder\'s code" and enter {code}. You will see your work orders and can claim the work you finish.': '{name}: FieldOS ഇൻസ്റ്റാൾ ചെയ്ത്, "സബ്കോൺട്രാക്ടറാണോ? ബിൽഡറുടെ കോഡ് ഉപയോഗിച്ച് സൗജന്യമായി ചേരുക" ടാപ്പ് ചെയ്ത് {code} നൽകുക. നിങ്ങളുടെ സബ്കോൺട്രാക്ട് ഓർഡറുകൾ കാണാം, തീർക്കുന്ന ജോലി ക്ലെയിം ചെയ്യാം.',
