  '{open} open across {sites} sites, {late} overdue': '{sites} സൈറ്റുകളിലായി {open} തുറന്നത്, {late} വൈകിയത്',
  '{qty} {unit} approved in {v} and not yet certified': '{v}-ൽ അംഗീകരിച്ച, ഇതുവരെ സർട്ടിഫൈ ചെയ്യാത്ത {qty} {unit}',
  '{q} approved, to certify': '{q} അംഗീകരിച്ചു, സർട്ടിഫൈ ചെയ്യാൻ',
  '{q} still to decide': '{q} ഇനിയും തീരുമാനിക്കാനുണ്ട്',
