  '{who}\'s claim of {qty} {unit} is waiting for certification': '{who}-യുടെ {qty} {unit} ക്ലെയിം സർട്ടിഫിക്കേഷനായി കാത്തിരിക്കുന്നു',
  'Approved variations to bill': 'ബിൽ ചെയ്യാനുള്ള അംഗീകരിച്ച വേരിയേഷനുകൾ',
  'Enter the client rate for each one to bill now. Leave a rate empty to leave it for a later bill.': 'ഇപ്പോൾ ബിൽ ചെയ്യാൻ ഓരോന്നിനും ക്ലയന്റ് നിരക്ക് നൽകുക. പിന്നീടുള്ള ബില്ലിലേക്ക് മാറ്റിവയ്ക്കാൻ നിരക്ക് ശൂന്യമായി വിടുക.',
  'A hold point stops work until it is inspected and released. A defect is fixed with a photo and checked by someone else.': 'പരിശോധിച്ച് റിലീസ് ചെയ്യുന്നതുവരെ ഹോൾഡ് പോയിന്റ് ജോലി നിർത്തിവയ്ക്കും. ഒരു ഡിഫക്റ്റ് ഫോട്ടോയോടെ ശരിയാക്കുകയും മറ്റൊരാൾ പരിശോധിക്കുകയും ചെയ്യും.',
  'Accept and close': 'സ്വീകരിച്ച് ക്ലോസ് ചെയ്യുക',
