  'Add a line': 'ഒരു വരി ചേർക്കുക',
  'Add a photo of the fix.': 'ശരിയാക്കിയതിന്റെ ഫോട്ടോ ചേർക്കുക.',
  'Add checklist line': 'ചെക്ക്‌ലിസ്റ്റ് വരി ചേർക്കുക',
  'Add drawing': 'ഡ്രോയിംഗ് ചേർക്കുക',
  'Add each flat, villa or zone. It can be handed over only when its defects are closed, hold points released and checklist done.': 'ഓരോ ഫ്ലാറ്റും വില്ലയും സോണും ചേർക്കുക. അതിന്റെ ഡിഫക്റ്റുകൾ ക്ലോസ് ചെയ്യുകയും ഹോൾഡ് പോയിന്റുകൾ റിലീസ് ചെയ്യുകയും ചെക്ക്‌ലിസ്റ്റ് തീർക്കുകയും ചെയ്താൽ മാത്രമേ കൈമാറാൻ കഴിയൂ.',
