  'Every site starts from these. A new unit gets the handover checklist, and the standard hold points can be added at any place on a site.': 'എല്ലാ സൈറ്റുകളും ഇവയിൽ നിന്നാണ് തുടങ്ങുന്നത്. ഒരു പുതിയ യൂണിറ്റിന് ഹാൻഡ്ഓവർ ചെക്ക്‌ലിസ്റ്റ് ലഭിക്കും, സ്റ്റാൻഡേർഡ് ഹോൾഡ് പോയിന്റുകൾ സൈറ്റിലെ ഏത് സ്ഥലത്തും ചേർക്കാം.',
