  'Keep every drawing and its revisions here. The site sees only the latest approved revision.': 'എല്ലാ ഡ്രോയിംഗുകളും അവയുടെ റിവിഷനുകളും ഇവിടെ സൂക്ഷിക്കുക. സൈറ്റിന് ഏറ്റവും പുതിയ അംഗീകരിച്ച റിവിഷൻ മാത്രമേ കാണാൻ കഴിയൂ.',
