  'Follow {site} on FieldOS: install it, tap "Supplier or client? Join free with the builder\'s code" and enter {code}. You will see the progress, photos, bills and payments.': 'FieldOS-ൽ {site} ഫോളോ ചെയ്യുക: ഇൻസ്റ്റാൾ ചെയ്യുക, "സപ്ലയറോ ക്ലയന്റോ? ബിൽഡറുടെ കോഡ് ഉപയോഗിച്ച് സൗജന്യമായി ചേരുക" ടാപ്പ് ചെയ്ത് {code} നൽകുക. പുരോഗതി, ഫോട്ടോകൾ, ബില്ലുകൾ, പേയ്മെന്റുകൾ എന്നിവ കാണാം.',
  'Follow-ups due': 'ഫോളോ-അപ്പ് ചെയ്യേണ്ടവ',
  'For': 'ആർക്ക്',
  'For site': 'സൈറ്റിന്',
  'For the company name and headings': 'കമ്പനിയുടെ പേരിനും തലക്കെട്ടുകൾക്കും',
  'Free for the builder\'s suppliers and clients. Suppliers answer price requests and say when an order is on its way. Clients see their site\'s progress, photos, bills and payments.': 'ബിൽഡറുടെ സപ്ലയർമാർക്കും ക്ലയന്റുകൾക്കും സൗജന്യം. സപ്ലയർമാർ വില അഭ്യർത്ഥനകൾക്ക് മറുപടി നൽകുകയും ഓർഡർ വഴിയിലാണെന്ന് അറിയിക്കുകയും ചെയ്യും. ക്ലയന്റുകൾക്ക് അവരുടെ സൈറ്റിന്റെ പുരോഗതി, ഫോട്ടോകൾ, ബില്ലുകൾ, പേയ്മെന്റുകൾ എന്നിവ കാണാം.',
  'Free for them. They see only the price requests you send them and their own orders.': 'അവർക്ക് സൗജന്യം. നിങ്ങൾ അയയ്ക്കുന്ന വില അഭ്യർത്ഥനകളും അവരുടെ സ്വന്തം ഓർഡറുകളും മാത്രമേ അവർ കാണൂ.',
  'Free for them. They see this site\'s progress, daily updates with photos, bills and payments. Not costs, suppliers or other sites.': 'അവർക്ക് സൗജന്യം. ഈ സൈറ്റിന്റെ പുരോഗതി, ഫോട്ടോകളോടെ ദിവസ അപ്ഡേറ്റുകൾ, ബില്ലുകൾ, പേയ്മെന്റുകൾ എന്നിവ അവർ കാണും. ചെലവുകൾ, സപ്ലയർമാർ, മറ്റ് സൈറ്റുകൾ എന്നിവ കാണില്ല.',
