  'Submitted late · {when}': 'വൈകി സമർപ്പിച്ചു · {when}',
  'Tap to see what is still to do. Quiet day? Mark it in seconds.': 'ഇനിയും ചെയ്യാനുള്ളത് കാണാൻ ടാപ്പ് ചെയ്യുക. ജോലി കുറഞ്ഞ ദിവസമാണോ? സെക്കൻഡുകൾക്കുള്ളിൽ അടയാളപ്പെടുത്തുക.',
  'Thanks. This helps fix the real cause.': 'നന്ദി. യഥാർത്ഥ കാരണം ശരിയാക്കാൻ ഇത് സഹായിക്കും.',
