  'RERA quarterly report is due': 'RERA പാദവാർഷിക റിപ്പോർട്ട് നൽകാൻ സമയമായി',
  'RERA quarterly report: 5 days left': 'RERA പാദവാർഷിക റിപ്പോർട്ട്: 5 ദിവസം ബാക്കി',
  'RERA registration number': 'RERA രജിസ്ട്രേഷൻ നമ്പർ',
  'Reinforcement steel': 'കമ്പി (റീഇൻഫോഴ്സ്മെന്റ് സ്റ്റീൽ)',
  'Sand': 'മണൽ',
  'Say why it is cancelled.': 'എന്തുകൊണ്ട് റദ്ദാക്കുന്നു എന്ന് പറയുക.',
  'Set the start date': 'തുടക്ക തീയതി നിശ്ചയിക്കുക',
  'Short {amount}': 'കുറവ് {amount}',
  'Short {amount} at counts': 'എണ്ണിയപ്പോൾ {amount} കുറവ്',
  'Should have used': 'ഉപയോഗിക്കേണ്ടിയിരുന്നത്',
  'Should have used = approved work × the norms. The norms are starting figures for nominal mixes; set your own in Material norms.': 'ഉപയോഗിക്കേണ്ടിയിരുന്നത് = അംഗീകരിച്ച ജോലി × മാനദണ്ഡങ്ങൾ. മാനദണ്ഡങ്ങൾ നോമിനൽ മിക്സുകൾക്കുള്ള തുടക്ക കണക്കുകളാണ്; മെറ്റീരിയൽ മാനദണ്ഡങ്ങളിൽ നിങ്ങളുടേത് നിശ്ചയിക്കുക.',
  'Slab cast': 'സ്ലാബ് വാർത്തു',
  'Starting figures for nominal mixes with a 50 kg cement bag. Change them to your own mix and wastage.': '50 kg സിമന്റ് ചാക്കുള്ള നോമിനൽ മിക്സുകൾക്കുള്ള തുടക്ക കണക്കുകൾ. നിങ്ങളുടെ മിക്സിനും പാഴാകലിനും അനുസരിച്ച് മാറ്റുക.',
  'Steel': 'സ്റ്റീൽ',
  'Take cash back': 'ക്യാഷ് തിരികെ വാങ്ങുക',
  'The book says {amount} in hand.': 'കണക്ക് പ്രകാരം കയ്യിൽ {amount} ഉണ്ട്.',
  'Upload to TS-RERA by {date}': '{date}-നകം TS-RERA-യിൽ അപ്‌ലോഡ് ചെയ്യുക',
  'Usage matches the work done': 'ഉപയോഗം ചെയ്ത ജോലിക്ക് യോജിക്കുന്നു',
  'Used, no work for it': 'ഉപയോഗിച്ചു, അതിന് ജോലിയില്ല',
  'Week 1 (baseline)': 'ആഴ്ച 1 (ബേസ്‌ലൈൻ)',
  'Week 1 is the baseline. At day 30 and day 60 the scorecard shows what changed, from what this site recorded: reports, cash, bills, challans, attendance and payments.': 'ആഴ്ച 1 ആണ് ബേസ്‌ലൈൻ. 30-ാം ദിവസവും 60-ാം ദിവസവും, ഈ സൈറ്റ് രേഖപ്പെടുത്തിയതിൽ നിന്ന് എന്ത് മാറി എന്ന് സ്കോർകാർഡ് കാണിക്കും: റിപ്പോർട്ടുകൾ, ക്യാഷ്, ബില്ലുകൾ, ഡെലിവറി നോട്ടുകൾ, ഹാജർ, പേയ്മെന്റുകൾ.',
  'When an expense, payment, delivery, bill or attendance entry is changed or deleted, what it was and who changed it shows here. It syncs from the cloud.': 'ഒരു ചെലവ്, പേയ്മെന്റ്, ഡെലിവറി, ബിൽ അല്ലെങ്കിൽ ഹാജർ എൻട്രി മാറ്റുകയോ ഡിലീറ്റ് ചെയ്യുകയോ ചെയ്യുമ്പോൾ, അത് എന്തായിരുന്നു, ആര് മാറ്റി എന്ന് ഇവിടെ കാണിക്കും. ഇത് ക്ലൗഡിൽ നിന്ന് സിങ്ക് ചെയ്യുന്നു.',
  'When did the pilot start?': 'പൈലറ്റ് എപ്പോൾ തുടങ്ങി?',
  'Within norm': 'മാനദണ്ഡത്തിനുള്ളിൽ',
  'Work measurement': 'ജോലി അളവ്',
  'Worse': 'മോശം',
  'Yes': 'അതെ',
  'bags': 'ചാക്ക്',
  'book said {amount}': 'കണക്കിൽ {amount} ആയിരുന്നു',
  'cu m': 'ക്യു. മീ',
  'kg': 'kg',
  'nos': 'എണ്ണം',
  'sq m': 'ച. മീ',
  '{amount} spent with no bill': '{amount} ബില്ലില്ലാതെ ചെലവാക്കി',
  '{block}, floor {floor}': '{block}, നില {floor}',
  '{names} and {n} more. Update the floors and make the PDF.': '{names}, കൂടാതെ {n} എണ്ണം കൂടി. നിലകൾ അപ്ഡേറ്റ് ചെയ്ത് PDF ഉണ്ടാക്കുക.',
  '{names}. Update the floors and make the PDF.': '{names}. നിലകൾ അപ്ഡേറ്റ് ചെയ്ത് PDF ഉണ്ടാക്കുക.',
  '{n} approved measurements checked': 'അംഗീകരിച്ച {n} അളവുകൾ പരിശോധിച്ചു',
  '{n} materials off by more than {pct}%': '{n} മെറ്റീരിയലുകൾ {pct}%-ൽ കൂടുതൽ വ്യത്യാസം',
  '{n} measurements not checked': '{n} അളവുകൾ പരിശോധിച്ചിട്ടില്ല',
  '{pct}% complete': '{pct}% പൂർത്തിയായി',
  '{pct}% over': '{pct}% കൂടുതൽ',
  '{pct}% under': '{pct}% കുറവ്',
  '{qty} more recorded in other units, not counted.': '{qty} കൂടി മറ്റ് യൂണിറ്റുകളിൽ രേഖപ്പെടുത്തി, എണ്ണിയിട്ടില്ല.',
  'A tax invoice number has up to 16 letters, digits, - or /, like INV-0001.': 'ടാക്സ് ഇൻവോയ്സ് നമ്പറിൽ 16 വരെ അക്ഷരങ്ങൾ, അക്കങ്ങൾ, - അല്ലെങ്കിൽ / ഉണ്ടാകാം, ഉദാ. INV-0001.',
  'Add your GSTIN in "Your details on bills" first. Without it a bill cannot charge GST; pick None.': 'ആദ്യം "ബില്ലുകളിലെ നിങ്ങളുടെ വിവരങ്ങൾ"-ൽ നിങ്ങളുടെ TRN ചേർക്കുക. അതില്ലാതെ ബില്ലിൽ VAT ഈടാക്കാനാകില്ല; ഒന്നുമില്ല തിരഞ്ഞെടുക്കുക.',
  'Anthropic in the USA, with Sarvam AI in India as a backup': 'USA-യിലെ Anthropic, ബാക്കപ്പായി ഇന്ത്യയിലെ Sarvam AI',
  'Ask FieldOS uses AI from other companies': 'Ask FieldOS മറ്റ് കമ്പനികളുടെ AI ഉപയോഗിക്കുന്നു',
  'Ask for a summary of my data': 'എന്റെ ഡാറ്റയുടെ ഒരു സംഗ്രഹം ചോദിക്കുക',
  'Ask to correct or erase my data': 'എന്റെ ഡാറ്റ തിരുത്താനോ മായ്ക്കാനോ ആവശ്യപ്പെടുക',
  'Ask us for a summary of your data, to correct or erase it, or to name someone to act for you. Write to info@mldynamic.com.': 'നിങ്ങളുടെ ഡാറ്റയുടെ സംഗ്രഹം, അത് തിരുത്താനോ മായ്ക്കാനോ, അല്ലെങ്കിൽ നിങ്ങൾക്കുവേണ്ടി പ്രവർത്തിക്കാൻ ഒരാളെ നിയോഗിക്കാനോ ഞങ്ങളോട് ആവശ്യപ്പെടുക. info@mldynamic.com-ലേക്ക് എഴുതുക.',
  'Bug and crash reports': 'ബഗ്, ക്രാഷ് റിപ്പോർട്ടുകൾ',
  'Complain to the Grievance Officer': 'ഗ്രീവൻസ് ഓഫീസറോട് പരാതിപ്പെടുക',
  'Complaints': 'പരാതികൾ',
  'For building work, GST follows the state where the site is. Inside your state it splits into CGST and SGST': 'നിർമ്മാണ ജോലിക്ക്, സൈറ്റ് ഉള്ള സംസ്ഥാനത്തിന് അനുസരിച്ചാണ് GST. നിങ്ങളുടെ സംസ്ഥാനത്തിനുള്ളിൽ അത് CGST, SGST എന്നിങ്ങനെ വിഭജിക്കും',
  'Google Play or the App Store take the payment. RevenueCat in the USA gets the purchase record so the app can check your plan. We never see card or UPI details.': 'Google Play അല്ലെങ്കിൽ App Store ആണ് പണം സ്വീകരിക്കുന്നത്. നിങ്ങളുടെ പ്ലാൻ പരിശോധിക്കാൻ USA-യിലെ RevenueCat-ന് വാങ്ങലിന്റെ രേഖ ലഭിക്കും. കാർഡ്, ഇൻസ്റ്റന്റ് ട്രാൻസ്ഫർ വിവരങ്ങൾ ഞങ്ങൾ ഒരിക്കലും കാണില്ല.',
  'I agree': 'ഞാൻ സമ്മതിക്കുന്നു',
  'In Team & sync. This also withdraws your consent.': 'Team & sync-ൽ. ഇത് നിങ്ങളുടെ സമ്മതവും പിൻവലിക്കും.',
  'Let Ask FieldOS send questions to AI': 'Ask FieldOS-നെ ചോദ്യങ്ങൾ AI-ലേക്ക് അയയ്ക്കാൻ അനുവദിക്കുക',
  'Location and selfies': 'ലൊക്കേഷനും സെൽഫികളും',
  'Name someone to act for me': 'എനിക്കുവേണ്ടി പ്രവർത്തിക്കാൻ ഒരാളെ നിയോഗിക്കുക',
  'Only what you send us, and crash details if that setting is on, so that we can fix problems.': 'നിങ്ങൾ ഞങ്ങൾക്ക് അയയ്ക്കുന്നത് മാത്രം, ആ സെറ്റിംഗ് ഓണാണെങ്കിൽ ക്രാഷ് വിവരങ്ങളും, പ്രശ്നങ്ങൾ പരിഹരിക്കാൻ.',
  'Only when you use it: what you ask, and the site details needed to answer, go to Anthropic in the USA (or Sarvam AI in India as a backup) to work out the reply. They do not use it to train their models.': 'നിങ്ങൾ ഉപയോഗിക്കുമ്പോൾ മാത്രം: നിങ്ങൾ ചോദിക്കുന്നതും ഉത്തരം നൽകാൻ വേണ്ട സൈറ്റ് വിവരങ്ങളും മറുപടി തയ്യാറാക്കാൻ USA-യിലെ Anthropic-ലേക്ക് (അല്ലെങ്കിൽ ബാക്കപ്പായി ഇന്ത്യയിലെ Sarvam AI-ലേക്ക്) പോകും. അവർ ഇത് അവരുടെ മോഡലുകളെ പരിശീലിപ്പിക്കാൻ ഉപയോഗിക്കില്ല.',
  'Paying for FieldOS': 'FieldOS-ന് പണം നൽകൽ',
  'Projects, reports, photos, attendance, wages and other records your company keeps. They stay on this phone, and in our cloud in Mumbai, India when Team & sync is on, so that your team can see them.': 'നിങ്ങളുടെ കമ്പനി സൂക്ഷിക്കുന്ന പ്രോജക്റ്റുകൾ, റിപ്പോർട്ടുകൾ, ഫോട്ടോകൾ, ഹാജർ, ശമ്പളം, മറ്റ് രേഖകൾ. അവ ഈ ഫോണിലും, Team & sync ഓണാണെങ്കിൽ ഇന്ത്യയിലെ മുംബൈയിലുള്ള ഞങ്ങളുടെ ക്ലൗഡിലും സൂക്ഷിക്കും, നിങ്ങളുടെ ടീമിന് കാണാൻ.',
  'Read the full privacy policy': 'പൂർണ്ണ സ്വകാര്യതാ നയം വായിക്കുക',
  'Site records': 'സൈറ്റ് രേഖകൾ',
  'The AI assistant': 'AI അസിസ്റ്റന്റ്',
  'To answer, FieldOS sends what you type or say, and the site details needed for the answer (such as project names, workers, tasks and amounts), to Anthropic in the USA. If Anthropic is not available, it goes to Sarvam AI in India instead. They work out the reply and do not use it to train their models. FieldOS keeps only how much you used the assistant.': 'ഉത്തരം നൽകാൻ, നിങ്ങൾ ടൈപ്പ് ചെയ്യുന്നതോ പറയുന്നതോ, ഉത്തരത്തിന് വേണ്ട സൈറ്റ് വിവരങ്ങളും (പ്രോജക്റ്റ് പേരുകൾ, തൊഴിലാളികൾ, ടാസ്കുകൾ, തുകകൾ തുടങ്ങിയവ) FieldOS USA-യിലെ Anthropic-ലേക്ക് അയയ്ക്കും. Anthropic ലഭ്യമല്ലെങ്കിൽ, അത് പകരം ഇന്ത്യയിലെ Sarvam AI-ലേക്ക് പോകും. അവർ മറുപടി തയ്യാറാക്കുന്നു, അവരുടെ മോഡലുകളെ പരിശീലിപ്പിക്കാൻ ഇത് ഉപയോഗിക്കില്ല. നിങ്ങൾ അസിസ്റ്റന്റ് എത്ര ഉപയോഗിച്ചു എന്ന് മാത്രമേ FieldOS സൂക്ഷിക്കൂ.',
  'What FieldOS collects and why': 'FieldOS എന്ത് ശേഖരിക്കുന്നു, എന്തിന്',
  'What is collected and why, your rights, and the AI assistant permission': 'എന്ത് ശേഖരിക്കുന്നു, എന്തിന്, നിങ്ങളുടെ അവകാശങ്ങൾ, AI അസിസ്റ്റന്റ് അനുമതി',
  'Write from the email address on your account. We reply within 30 days. If you are not satisfied, you can complain to the Data Protection Board of India.': 'നിങ്ങളുടെ അക്കൗണ്ടിലെ ഇമെയിൽ വിലാസത്തിൽ നിന്ന് എഴുതുക. 30 ദിവസത്തിനുള്ളിൽ ഞങ്ങൾ മറുപടി നൽകും. തൃപ്തിയില്ലെങ്കിൽ, നിങ്ങൾക്ക് ഇന്ത്യയിലെ ഡാറ്റ പ്രൊട്ടക്ഷൻ ബോർഡിൽ പരാതിപ്പെടാം.',
  'Write to our Grievance Officer at info@mldynamic.com. We reply within 30 days. You can also complain to the Data Protection Board of India.': 'info@mldynamic.com-ൽ ഞങ്ങളുടെ ഗ്രീവൻസ് ഓഫീസർക്ക് എഴുതുക. 30 ദിവസത്തിനുള്ളിൽ ഞങ്ങൾ മറുപടി നൽകും. ഇന്ത്യയിലെ ഡാറ്റ പ്രൊട്ടക്ഷൻ ബോർഡിലും നിങ്ങൾക്ക് പരാതിപ്പെടാം.',
  'Write to {email} with "{subject}" as the subject.': '"{subject}" എന്ന വിഷയത്തോടെ {email}-ലേക്ക് എഴുതുക.',
  'You can stop the AI assistant, turn off crash details, export your records or delete your cloud account at any time. Stopping does not change what was done before.': 'നിങ്ങൾക്ക് എപ്പോൾ വേണമെങ്കിലും AI അസിസ്റ്റന്റ് നിർത്താം, ക്രാഷ് വിവരങ്ങൾ ഓഫാക്കാം, രേഖകൾ എക്സ്പോർട്ട് ചെയ്യാം, അല്ലെങ്കിൽ ക്ലൗഡ് അക്കൗണ്ട് ഡിലീറ്റ് ചെയ്യാം. നിർത്തുന്നത് മുമ്പ് ചെയ്തതിനെ മാറ്റില്ല.',
  'You can stop this at any time in Settings, Your privacy.': 'സെറ്റിംഗ്സ്, നിങ്ങളുടെ സ്വകാര്യത എന്നതിൽ എപ്പോൾ വേണമെങ്കിലും ഇത് നിർത്താം.',
  'Your account': 'നിങ്ങളുടെ അക്കൗണ്ട്',
  'Your choices': 'നിങ്ങളുടെ തിരഞ്ഞെടുപ്പുകൾ',
  'Your location, and a selfie, only when you check in or out, punch a worker in, set a site location or take a site photo, to show the work was done at the site. Never in the background.': 'നിങ്ങളുടെ ലൊക്കേഷനും ഒരു സെൽഫിയും, നിങ്ങൾ ചെക്ക് ഇൻ അല്ലെങ്കിൽ ഔട്ട് ചെയ്യുമ്പോഴോ, ഒരു തൊഴിലാളിയെ പഞ്ച് ഇൻ ചെയ്യുമ്പോഴോ, സൈറ്റ് ലൊക്കേഷൻ നിശ്ചയിക്കുമ്പോഴോ, സൈറ്റ് ഫോട്ടോ എടുക്കുമ്പോഴോ മാത്രം, ജോലി സൈറ്റിൽ ചെയ്തു എന്ന് കാണിക്കാൻ. ഒരിക്കലും പശ്ചാത്തലത്തിൽ ഇല്ല.',
  'Your name, email address and the company you join, so that you can sign in and work with your team.': 'നിങ്ങളുടെ പേര്, ഇമെയിൽ വിലാസം, നിങ്ങൾ ചേരുന്ന കമ്പനി, സൈൻ ഇൻ ചെയ്യാനും ടീമിനൊപ്പം ജോലി ചെയ്യാനും.',
  'Your privacy': 'നിങ്ങളുടെ സ്വകാര്യത',
  'Your rights': 'നിങ്ങളുടെ അവകാശങ്ങൾ',
  'A Zoho Books file, with tax split out': 'ടാക്സ് വേർതിരിച്ച ഒരു Zoho Books ഫയൽ',
  'Add your tax number and address': 'നിങ്ങളുടെ ടാക്സ് നമ്പറും വിലാസവും ചേർക്കുക',
  'Client\'s {label} (optional)': 'ക്ലയന്റിന്റെ {label} (നിർബന്ധമില്ല)',
  'Kept back by the client for the tax office': 'ടാക്സ് ഓഫീസിനായി ക്ലയന്റ് പിടിച്ചുവെച്ചത്',
  '{tax} rate': '{tax} നിരക്ക്',
  'Job records': 'ജോലി രേഖകൾ',
  'Projects, logs, photos, time cards, pay and other records your company keeps. They stay on this phone, and in our cloud when Team & sync is on, so that your team can see them. Our cloud is in India today.': 'നിങ്ങളുടെ കമ്പനി സൂക്ഷിക്കുന്ന പ്രോജക്റ്റുകൾ, ലോഗുകൾ, ഫോട്ടോകൾ, ടൈം കാർഡുകൾ, ശമ്പളം, മറ്റ് രേഖകൾ. അവ ഈ ഫോണിലും, Team & sync ഓണാണെങ്കിൽ ഞങ്ങളുടെ ക്ലൗഡിലും സൂക്ഷിക്കും, നിങ്ങളുടെ ടീമിന് കാണാൻ. ഞങ്ങളുടെ ക്ലൗഡ് ഇപ്പോൾ ഇന്ത്യയിലാണ്.',
  'Location and photo check-in': 'ലൊക്കേഷനും ഫോട്ടോ ചെക്ക് ഇന്നും',
  'Your location, and a photo, only when you clock in or out, clock a worker in, set a job location or take a job photo, to show the work was done on the job. Never in the background. FieldOS does not use face recognition and keeps no face scan.': 'നിങ്ങളുടെ ലൊക്കേഷനും ഒരു ഫോട്ടോയും, നിങ്ങൾ ക്ലോക്ക് ഇൻ അല്ലെങ്കിൽ ഔട്ട് ചെയ്യുമ്പോഴോ, ഒരു തൊഴിലാളിയെ ക്ലോക്ക് ഇൻ ചെയ്യുമ്പോഴോ, ജോലി ലൊക്കേഷൻ നിശ്ചയിക്കുമ്പോഴോ, ജോലി ഫോട്ടോ എടുക്കുമ്പോഴോ മാത്രം, ജോലി അവിടെ ചെയ്തു എന്ന് കാണിക്കാൻ. ഒരിക്കലും പശ്ചാത്തലത്തിൽ ഇല്ല. FieldOS മുഖം തിരിച്ചറിയൽ ഉപയോഗിക്കുന്നില്ല, മുഖ സ്കാൻ സൂക്ഷിക്കുന്നില്ല.',
  'Only when you use it: what you ask, and the job details needed to answer, go to Anthropic in the USA (or Sarvam AI in India as a backup) to work out the reply. Photos and locations are never sent. They do not use it to train their models.': 'നിങ്ങൾ ഉപയോഗിക്കുമ്പോൾ മാത്രം: നിങ്ങൾ ചോദിക്കുന്നതും ഉത്തരം നൽകാൻ വേണ്ട ജോലി വിവരങ്ങളും മറുപടി തയ്യാറാക്കാൻ USA-യിലെ Anthropic-ലേക്ക് (അല്ലെങ്കിൽ ബാക്കപ്പായി ഇന്ത്യയിലെ Sarvam AI-ലേക്ക്) പോകും. ഫോട്ടോകളും ലൊക്കേഷനുകളും ഒരിക്കലും അയയ്ക്കില്ല. അവർ ഇത് അവരുടെ മോഡലുകളെ പരിശീലിപ്പിക്കാൻ ഉപയോഗിക്കില്ല.',
  'Google Play or the App Store take the payment. RevenueCat in the USA gets the purchase record so the app can check your plan. We never see card details.': 'Google Play അല്ലെങ്കിൽ App Store ആണ് പണം സ്വീകരിക്കുന്നത്. നിങ്ങളുടെ പ്ലാൻ പരിശോധിക്കാൻ USA-യിലെ RevenueCat-ന് വാങ്ങലിന്റെ രേഖ ലഭിക്കും. കാർഡ് വിവരങ്ങൾ ഞങ്ങൾ ഒരിക്കലും കാണില്ല.',
  'You can stop the AI assistant, turn off crash details, export your records or delete your cloud account at any time. We do not sell or share your personal information, and we do not use it for targeted ads.': 'നിങ്ങൾക്ക് എപ്പോൾ വേണമെങ്കിലും AI അസിസ്റ്റന്റ് നിർത്താം, ക്രാഷ് വിവരങ്ങൾ ഓഫാക്കാം, രേഖകൾ എക്സ്പോർട്ട് ചെയ്യാം, അല്ലെങ്കിൽ ക്ലൗഡ് അക്കൗണ്ട് ഡിലീറ്റ് ചെയ്യാം. ഞങ്ങൾ നിങ്ങളുടെ വ്യക്തിഗത വിവരങ്ങൾ വിൽക്കുകയോ പങ്കിടുകയോ ചെയ്യുന്നില്ല, ടാർഗെറ്റഡ് പരസ്യങ്ങൾക്ക് ഉപയോഗിക്കുന്നില്ല.',
  'Your privacy rights': 'നിങ്ങളുടെ സ്വകാര്യതാ അവകാശങ്ങൾ',
  'Ask us what we hold about you, to correct it, delete it or get a copy, or let someone act for you. Write to info@mldynamic.com. We reply within 45 days.': 'നിങ്ങളെക്കുറിച്ച് ഞങ്ങളുടെ കയ്യിൽ എന്തുണ്ടെന്ന് ചോദിക്കുക, അത് തിരുത്താനോ ഡിലീറ്റ് ചെയ്യാനോ ഒരു കോപ്പി ലഭിക്കാനോ, അല്ലെങ്കിൽ നിങ്ങൾക്കുവേണ്ടി ഒരാളെ പ്രവർത്തിക്കാൻ അനുവദിക്കാനോ. info@mldynamic.com-ലേക്ക് എഴുതുക. 45 ദിവസത്തിനുള്ളിൽ ഞങ്ങൾ മറുപടി നൽകും.',
  'Appeals': 'അപ്പീലുകൾ',
  'If we turn down a request, write to info@mldynamic.com with the word "Appeal" and we will look at it again. If you are still not satisfied, you can contact your state attorney general.': 'ഞങ്ങൾ ഒരു അഭ്യർത്ഥന നിരസിച്ചാൽ, "Appeal" എന്ന വാക്കോടെ info@mldynamic.com-ലേക്ക് എഴുതുക, ഞങ്ങൾ അത് വീണ്ടും പരിശോധിക്കും. എന്നിട്ടും തൃപ്തിയില്ലെങ്കിൽ, നിങ്ങളുടെ സംസ്ഥാന അറ്റോർണി ജനറലിനെ ബന്ധപ്പെടാം.',
  'Appeal a privacy decision': 'ഒരു സ്വകാര്യതാ തീരുമാനത്തിനെതിരെ അപ്പീൽ നൽകുക',
  'Write from the email address on your account. We reply within 45 days. If you are not satisfied, you can appeal, and then contact the authority for privacy where you live.': 'നിങ്ങളുടെ അക്കൗണ്ടിലെ ഇമെയിൽ വിലാസത്തിൽ നിന്ന് എഴുതുക. 45 ദിവസത്തിനുള്ളിൽ ഞങ്ങൾ മറുപടി നൽകും. തൃപ്തിയില്ലെങ്കിൽ, അപ്പീൽ നൽകാം, തുടർന്ന് നിങ്ങൾ താമസിക്കുന്നിടത്തെ സ്വകാര്യതാ അതോറിറ്റിയെ ബന്ധപ്പെടാം.',
  'Bar size (#3 to #18)': 'കമ്പി വലിപ്പം (#3 മുതൽ #18 വരെ)',
  '{lb} lb per foot': 'ഒരു അടിക്ക് {lb} lb',
  '{lb} lb for {ft} ft': '{ft} അടിക്ക് {lb} lb',
  'Standard rebar weights (ASTM A615). Bar #4 is 4/8 inch across.': 'സ്റ്റാൻഡേർഡ് റീബാർ ഭാരങ്ങൾ (ASTM A615). ബാർ #4-ന്റെ വ്യാസം 4/8 ഇഞ്ച്.',
  'count': 'എണ്ണം',
  'Foot': 'അടി',
  'Hectare': 'ഹെക്ടർ',
  'Yard': 'യാർഡ്',
  'Meter': 'മീറ്റർ',
  'Square yard': 'ചതുരശ്ര യാർഡ്',
  'Square (100 sq ft, roofing)': 'സ്ക്വയർ (100 ച. അടി, റൂഫിംഗ്)',
  'Square meter': 'ചതുരശ്ര മീറ്റർ',
  'Cubic yard': 'ക്യൂബിക് യാർഡ്',
  'Gallon (US)': 'ഗാലൻ (US)',
  'Cubic meter': 'ക്യൂബിക് മീറ്റർ',
  'Pound': 'പൗണ്ട്',
  'Ton (2,000 lb)': 'ടൺ (2,000 lb)',
  'Cement bag (94 lb)': 'സിമന്റ് ചാക്ക് (94 lb)',
  'Add your {label} in "Your details on bills" first. Without it a bill cannot charge {tax}; pick None.': 'ആദ്യം "ബില്ലുകളിലെ നിങ്ങളുടെ വിവരങ്ങൾ"-ൽ നിങ്ങളുടെ {label} ചേർക്കുക. അതില്ലാതെ ബില്ലിൽ {tax} ഈടാക്കാനാകില്ല; ഒന്നുമില്ല തിരഞ്ഞെടുക്കുക.',
  'This site has only {qty} on record.': 'ഈ സൈറ്റിന്റെ രേഖയിൽ {qty} മാത്രമേ ഉള്ളൂ.',
  'Expired permit': 'കാലാവധി കഴിഞ്ഞ പെർമിറ്റ്',
  '{what} has expired. Working on site without it can break the law. Renew it first if you can.': '{what} കാലാവധി കഴിഞ്ഞു. അതില്ലാതെ സൈറ്റിൽ ജോലി ചെയ്യുന്നത് നിയമലംഘനമാകാം. കഴിയുമെങ്കിൽ ആദ്യം പുതുക്കുക.',
  'Punch in anyway': 'എന്നാലും പഞ്ച് ഇൻ ചെയ്യുക',
  'A permit or card expires soon': 'ഒരു പെർമിറ്റിന്റെയോ കാർഡിന്റെയോ കാലാവധി ഉടൻ കഴിയും',
  '{n} permits or cards expire soon': '{n} പെർമിറ്റുകളുടെയോ കാർഡുകളുടെയോ കാലാവധി ഉടൻ കഴിയും',
  'Permits and cards': 'പെർമിറ്റുകളും കാർഡുകളും',
  'A permit or card has expired': 'ഒരു പെർമിറ്റിന്റെയോ കാർഡിന്റെയോ കാലാവധി കഴിഞ്ഞു',
  '{days} days left': '{days} ദിവസം ബാക്കി',
  'Valid': 'സാധുവാണ്',
  'No permits yet. Open a worker and add their permits and cards, with the expiry dates.': 'ഇതുവരെ പെർമിറ്റുകൾ ഇല്ല. ഒരു തൊഴിലാളിയെ തുറന്ന് അവരുടെ പെർമിറ്റുകളും കാർഡുകളും കാലാവധി തീയതികളോടെ ചേർക്കുക.',
  'Reminders come 90, 60, 30 and 7 days before each date. Renew before the date, not after.': 'ഓരോ തീയതിക്കും 90, 60, 30, 7 ദിവസം മുമ്പ് റിമൈൻഡറുകൾ വരും. തീയതിക്ക് മുമ്പ് പുതുക്കുക, ശേഷമല്ല.',
  'Not added': 'ചേർത്തിട്ടില്ല',
  'Expires {date}': 'കാലാവധി {date}',
  'Number (optional)': 'നമ്പർ (നിർബന്ധമില്ല)',
  'Expiry date': 'കാലാവധി തീയതി',
  'Pick a date': 'ഒരു തീയതി തിരഞ്ഞെടുക്കുക',
  'PLKS work permit': 'PLKS വർക്ക് പെർമിറ്റ്',
  'CIDB Green Card': 'CIDB ഗ്രീൻ കാർഡ്',
  'Passport': 'പാസ്പോർട്ട്',
  'FOMEMA medical': 'FOMEMA മെഡിക്കൽ',
  'Work permit and residence visa': 'വർക്ക് പെർമിറ്റും റസിഡൻസ് വിസയും',
  'Emirates ID': 'എമിറേറ്റ്സ് ഐഡി',
  'CSCS card': 'CSCS കാർഡ്',
  'Right to work (visa)': 'ജോലി ചെയ്യാനുള്ള അവകാശം (വിസ)',
  'Contract sum': 'കരാർ തുക',
  'Retention stops at {pct}% of it': 'റിറ്റൻഷൻ അതിന്റെ {pct}%-ൽ നിൽക്കും',
  'Too many wrong PINs. Wait {time}.': 'തെറ്റായ PIN-കൾ കൂടുതലായി. {time} കാത്തിരിക്കുക.',
  'Tries left before sign-out: {n}': 'സൈൻ ഔട്ടിന് മുമ്പ് ബാക്കിയുള്ള ശ്രമങ്ങൾ: {n}',
  'Too many wrong PINs. The app lock is off. Log in again with your password.': 'തെറ്റായ PIN-കൾ കൂടുതലായി. ആപ്പ് ലോക്ക് ഓഫായി. പാസ്‌വേഡ് ഉപയോഗിച്ച് വീണ്ടും ലോഗിൻ ചെയ്യുക.',
  'Offline for over 7 days. Connect to the internet to keep making changes. You can still view everything.': '7 ദിവസത്തിലേറെയായി ഓഫ്‌ലൈനാണ്. മാറ്റങ്ങൾ വരുത്തുന്നത് തുടരാൻ ഇന്റർനെറ്റുമായി കണക്റ്റ് ചെയ്യുക. നിങ്ങൾക്ക് ഇപ്പോഴും എല്ലാം കാണാം.',
  'Your company plan has ended. Connect to the internet to check it. You can still view everything.': 'നിങ്ങളുടെ കമ്പനി പ്ലാൻ അവസാനിച്ചു. പരിശോധിക്കാൻ ഇന്റർനെറ്റുമായി കണക്റ്റ് ചെയ്യുക. നിങ്ങൾക്ക് ഇപ്പോഴും എല്ലാം കാണാം.',
  'Rest day and public holidays': 'വിശ്രമ ദിവസവും പൊതു അവധികളും',
  'Work on the rest day pays 1 day for up to half the normal hours and 2 days for more. Work on a public holiday pays 2 days on top of the holiday pay. A day you mark by hand keeps your mark.': 'വിശ്രമ ദിവസത്തെ ജോലിക്ക്, സാധാരണ സമയത്തിന്റെ പകുതി വരെ 1 ദിവസവും കൂടുതലായാൽ 2 ദിവസവും ശമ്പളം. പൊതു അവധിയിലെ ജോലിക്ക് അവധി ശമ്പളത്തിന് പുറമെ 2 ദിവസത്തെ ശമ്പളം. നിങ്ങൾ കൈകൊണ്ട് അടയാളപ്പെടുത്തിയ ദിവസം നിങ്ങളുടെ അടയാളം നിലനിർത്തും.',
  'Rest day': 'വിശ്രമ ദിവസം',
  'Friday (Kelantan, Terengganu, Kedah)': 'വെള്ളിയാഴ്ച (കെലന്താൻ, തെരെംഗാനു, കെഡ)',
  'Public holidays': 'പൊതു അവധികൾ',
  'Add the federal and state holidays your company gives, from the gazette for your state.': 'നിങ്ങളുടെ കമ്പനി നൽകുന്ന ഫെഡറൽ, സംസ്ഥാന അവധികൾ നിങ്ങളുടെ സംസ്ഥാനത്തിന്റെ ഗസറ്റിൽ നിന്ന് ചേർക്കുക.',
  'Projects, reports, photos, attendance, wages, work permits and other records your company keeps. They stay on this phone, and in our cloud in Mumbai, India when Team & sync is on, so that your team can see them. Your company decides what it records and is responsible for it.': 'നിങ്ങളുടെ കമ്പനി സൂക്ഷിക്കുന്ന പ്രോജക്റ്റുകൾ, റിപ്പോർട്ടുകൾ, ഫോട്ടോകൾ, ഹാജർ, ശമ്പളം, വർക്ക് പെർമിറ്റുകൾ, മറ്റ് രേഖകൾ. അവ ഈ ഫോണിലും, Team & sync ഓണാണെങ്കിൽ ഇന്ത്യയിലെ മുംബൈയിലുള്ള ഞങ്ങളുടെ ക്ലൗഡിലും സൂക്ഷിക്കും, നിങ്ങളുടെ ടീമിന് കാണാൻ. എന്ത് രേഖപ്പെടുത്തണമെന്ന് നിങ്ങളുടെ കമ്പനി തീരുമാനിക്കുന്നു, അതിന്റെ ഉത്തരവാദിത്തം കമ്പനിക്കാണ്.',
  'Your location, and a selfie if your company uses selfie attendance, only when you check in or out, punch a worker in, set a site location or take a site photo, to show the work was done at the site. Never in the background. FieldOS does not use face recognition.': 'നിങ്ങളുടെ ലൊക്കേഷനും, കമ്പനി സെൽഫി ഹാജർ ഉപയോഗിക്കുന്നുണ്ടെങ്കിൽ ഒരു സെൽഫിയും, നിങ്ങൾ ചെക്ക് ഇൻ അല്ലെങ്കിൽ ഔട്ട് ചെയ്യുമ്പോഴോ, ഒരു തൊഴിലാളിയെ പഞ്ച് ഇൻ ചെയ്യുമ്പോഴോ, സൈറ്റ് ലൊക്കേഷൻ നിശ്ചയിക്കുമ്പോഴോ, സൈറ്റ് ഫോട്ടോ എടുക്കുമ്പോഴോ മാത്രം, ജോലി സൈറ്റിൽ ചെയ്തു എന്ന് കാണിക്കാൻ. ഒരിക്കലും പശ്ചാത്തലത്തിൽ ഇല്ല. FieldOS മുഖം തിരിച്ചറിയൽ ഉപയോഗിക്കുന്നില്ല.',
  'Data sent outside Malaysia': 'മലേഷ്യയ്ക്ക് പുറത്തേക്ക് അയയ്ക്കുന്ന ഡാറ്റ',
  'Our cloud is in India, and the services above are in India and the USA. Each gets only what it needs, under a contract that requires it to keep the data safe.': 'ഞങ്ങളുടെ ക്ലൗഡ് ഇന്ത്യയിലാണ്, മുകളിലുള്ള സേവനങ്ങൾ ഇന്ത്യയിലും USA-യിലുമാണ്. ഓരോന്നിനും അതിന് ആവശ്യമുള്ളത് മാത്രം ലഭിക്കും, ഡാറ്റ സുരക്ഷിതമായി സൂക്ഷിക്കണമെന്ന് നിർബന്ധമാക്കുന്ന കരാർ പ്രകാരം.',
  'Your rights under the PDPA': 'PDPA പ്രകാരമുള്ള നിങ്ങളുടെ അവകാശങ്ങൾ',
  'Ask us for access to your data or a copy, to correct it, or to send it to another organisation. Write to info@mldynamic.com. We reply within 21 days.': 'നിങ്ങളുടെ ഡാറ്റ കാണാനോ അതിന്റെ ഒരു കോപ്പി ലഭിക്കാനോ, അത് തിരുത്താനോ, മറ്റൊരു സ്ഥാപനത്തിലേക്ക് അയയ്ക്കാനോ ഞങ്ങളോട് ആവശ്യപ്പെടുക. info@mldynamic.com-ലേക്ക് എഴുതുക. 21 ദിവസത്തിനുള്ളിൽ ഞങ്ങൾ മറുപടി നൽകും.',
  'Write to info@mldynamic.com with "Privacy" in the subject. If you are not satisfied, you can complain to the Personal Data Protection Commissioner of Malaysia.': 'വിഷയത്തിൽ "Privacy" എന്ന് ചേർത്ത് info@mldynamic.com-ലേക്ക് എഴുതുക. തൃപ്തിയില്ലെങ്കിൽ, മലേഷ്യയിലെ പേഴ്സണൽ ഡാറ്റ പ്രൊട്ടക്ഷൻ കമ്മീഷണറോട് പരാതിപ്പെടാം.',
  'Minimum wage: RM1,700 a month (Minimum Wages Order 2025). In Sabah and Sarawak, the Sabah Labour Ordinance or the Sarawak Labour Ordinance applies instead of the Employment Act 1955 for overtime, rest days and holidays: check the rules for your site.': 'മിനിമം വേതനം: മാസം RM1,700 (Minimum Wages Order 2025). സബായിലും സരവാക്കിലും, ഓവർടൈം, വിശ്രമ ദിവസങ്ങൾ, അവധികൾ എന്നിവയ്ക്ക് Employment Act 1955-ന് പകരം Sabah Labour Ordinance അല്ലെങ്കിൽ Sarawak Labour Ordinance ബാധകമാണ്: നിങ്ങളുടെ സൈറ്റിന്റെ നിയമങ്ങൾ പരിശോധിക്കുക.',
  'below the minimum wage of {amount}/day': 'ദിവസം {amount} എന്ന മിനിമം വേതനത്തിന് താഴെ',
  'Write from the email address on your account. We reply within 21 days. If you are not satisfied, you can complain to the Personal Data Protection Commissioner of Malaysia.': 'നിങ്ങളുടെ അക്കൗണ്ടിലെ ഇമെയിൽ വിലാസത്തിൽ നിന്ന് എഴുതുക. 21 ദിവസത്തിനുള്ളിൽ ഞങ്ങൾ മറുപടി നൽകും. തൃപ്തിയില്ലെങ്കിൽ, മലേഷ്യയിലെ പേഴ്സണൽ ഡാറ്റ പ്രൊട്ടക്ഷൻ കമ്മീഷണറോട് പരാതിപ്പെടാം.',
  'Midday break season': 'ഉച്ച വിശ്രമ സീസൺ',
  'No outdoor work from {from} to {to} until {end}. Give shade, water and rest.': '{end} വരെ ദിവസവും {from} മുതൽ {to} വരെ പുറത്ത് ജോലിയില്ല. തണൽ, വെള്ളം, വിശ്രമം നൽകുക.',
  'Midday break': 'ഉച്ച വിശ്രമം',
  'Outdoor work in the sun is not allowed from {from} to {to}, 15 June to 15 September. Punch in only for indoor or shaded work, or work that is exempt, such as a concrete pour that cannot stop.': 'ജൂൺ 15 മുതൽ സെപ്റ്റംബർ 15 വരെ, {from} മുതൽ {to} വരെ വെയിലത്ത് പുറത്ത് ജോലി ചെയ്യാൻ അനുവാദമില്ല. അകത്തോ തണലിലോ ഉള്ള ജോലിക്കോ, ഇളവുള്ള ജോലിക്കോ മാത്രം പഞ്ച് ഇൻ ചെയ്യുക, ഉദാഹരണത്തിന് നിർത്താൻ പറ്റാത്ത കോൺക്രീറ്റ് വാർപ്പ്.',
  'Indoor or exempt work': 'അകത്തെ ജോലി അല്ലെങ്കിൽ ഇളവുള്ള ജോലി',
  'That TRN doesn\'t look right. It has 15 digits, like 100123456700003.': 'ഈ TRN ശരിയല്ലെന്ന് തോന്നുന്നു. ഇതിൽ 15 അക്കങ്ങൾ ഉണ്ടാകും, ഉദാഹരണത്തിന് 100123456700003.',
  'Write from the email address on your account. We reply within 30 days. If you are not satisfied, you can complain to the UAE data protection authority.': 'നിങ്ങളുടെ അക്കൗണ്ടിലുള്ള ഇമെയിൽ വിലാസത്തിൽ നിന്ന് എഴുതുക. 30 ദിവസത്തിനുള്ളിൽ ഞങ്ങൾ മറുപടി നൽകും. നിങ്ങൾക്ക് തൃപ്തിയില്ലെങ്കിൽ, UAE ഡാറ്റ സംരക്ഷണ അതോറിറ്റിയിൽ പരാതി നൽകാം.',
  'Data sent outside the UAE': 'UAE-ക്ക് പുറത്തേക്ക് അയയ്ക്കുന്ന ഡാറ്റ',
  'Our cloud is in India, and the services above are in India and the USA. Each gets only what it needs, under a contract that requires it to protect the data.': 'ഞങ്ങളുടെ ക്ലൗഡ് ഇന്ത്യയിലാണ്, മുകളിൽ പറഞ്ഞ സേവനങ്ങൾ ഇന്ത്യയിലും അമേരിക്കയിലുമാണ്. ഓരോന്നിനും ആവശ്യമുള്ളത് മാത്രമേ ലഭിക്കൂ, ഡാറ്റ സംരക്ഷിക്കണമെന്ന് നിർബന്ധമാക്കുന്ന ഒരു കരാർ പ്രകാരം.',
  'Your rights under the PDPL': 'PDPL പ്രകാരം നിങ്ങളുടെ അവകാശങ്ങൾ',
  'Ask us for a copy of your data, to correct or erase it, to stop using it, or to send it to another organisation. Write to info@mldynamic.com. We reply within 30 days.': 'നിങ്ങളുടെ ഡാറ്റയുടെ ഒരു കോപ്പി ചോദിക്കാനോ, അത് തിരുത്താനോ മായ്ക്കാനോ, അത് ഉപയോഗിക്കുന്നത് നിർത്താനോ, മറ്റൊരു സ്ഥാപനത്തിലേക്ക് അയയ്ക്കാനോ ഞങ്ങളോട് ആവശ്യപ്പെടുക. info@mldynamic.com എന്ന വിലാസത്തിലേക്ക് എഴുതുക. 30 ദിവസത്തിനുള്ളിൽ ഞങ്ങൾ മറുപടി നൽകും.',
  'Write to info@mldynamic.com with "Privacy" in the subject. If you are not satisfied, you can complain to the UAE data protection authority.': 'വിഷയത്തിൽ "Privacy" എന്ന് ചേർത്ത് info@mldynamic.com എന്ന വിലാസത്തിലേക്ക് എഴുതുക. നിങ്ങൾക്ക് തൃപ്തിയില്ലെങ്കിൽ, UAE ഡാറ്റ സംരക്ഷണ അതോറിറ്റിയിൽ പരാതി നൽകാം.',
  'CIS work for a VAT-registered contractor who is not the end user. The VAT is shown, and the customer pays it to HMRC.': 'അന്തിമ ഉപയോക്താവല്ലാത്ത VAT രജിസ്റ്റർ ചെയ്ത കരാറുകാരനുള്ള CIS ജോലി. VAT കാണിക്കും, ഉപഭോക്താവ് അത് HMRC-ക്ക് അടയ്ക്കും.',
  'Domestic reverse charge': 'ആഭ്യന്തര റിവേഴ്സ് ചാർജ്',
  'Materials or plant hire': 'സാമഗ്രികൾ അല്ലെങ്കിൽ യന്ത്ര വാടക',
  'No CIS is taken off this line': 'ഈ വരിയിൽ നിന്ന് CIS പിടിക്കില്ല',
  '{tax} (reverse charge, not added)': '{tax} (റിവേഴ്സ് ചാർജ്, ചേർത്തിട്ടില്ല)',
  'below the minimum wage of {amount}/hr': 'മിനിമം വേതനം {amount}/മണിക്കൂറിൽ താഴെ',
  'Your location and a selfie when you check in or out, and your location when you punch a worker in, set a site location or take a site photo, to show the work was done at the site. The app asks you first. Never in the background. FieldOS does not use face recognition.': 'നിങ്ങൾ ചെക്ക് ഇൻ അല്ലെങ്കിൽ ചെക്ക് ഔട്ട് ചെയ്യുമ്പോൾ നിങ്ങളുടെ ലൊക്കേഷനും ഒരു സെൽഫിയും, ഒരു തൊഴിലാളിയെ പഞ്ച് ഇൻ ചെയ്യുമ്പോഴോ സൈറ്റ് ലൊക്കേഷൻ സജ്ജമാക്കുമ്പോഴോ സൈറ്റ് ഫോട്ടോ എടുക്കുമ്പോഴോ നിങ്ങളുടെ ലൊക്കേഷനും, ജോലി സൈറ്റിൽ നടന്നുവെന്ന് കാണിക്കാൻ. ആപ്പ് ആദ്യം നിങ്ങളോട് ചോദിക്കും. ഒരിക്കലും പശ്ചാത്തലത്തിൽ ഇല്ല. FieldOS മുഖം തിരിച്ചറിയൽ ഉപയോഗിക്കുന്നില്ല.',
  'Write from the email address on your account. We reply within one month. If you are not satisfied, you can complain to the Information Commissioner\'s Office.': 'നിങ്ങളുടെ അക്കൗണ്ടിലെ ഇമെയിൽ വിലാസത്തിൽ നിന്ന് എഴുതുക. ഒരു മാസത്തിനകം ഞങ്ങൾ മറുപടി നൽകും. തൃപ്തരല്ലെങ്കിൽ, Information Commissioner\'s Office-ൽ പരാതി നൽകാം.',
  'Gross payment status (0%)': 'ഗ്രോസ് പേയ്‌മെന്റ് സ്റ്റാറ്റസ് (0%)',
  'Registered (20%)': 'രജിസ്റ്റർ ചെയ്തവർ (20%)',
  'Not registered (30%)': 'രജിസ്റ്റർ ചെയ്യാത്തവർ (30%)',
  'Add the people on a monthly salary. Each month FieldOS works out their pay for the days worked, EPF, SOCSO, EIS and advance recovery, and makes the payslips.': 'മാസ ശമ്പളക്കാരെ ചേർക്കുക. ഓരോ മാസവും FieldOS ജോലി ചെയ്ത ദിവസങ്ങളുടെ ശമ്പളം, EPF, SOCSO, EIS, അഡ്വാൻസ് തിരിച്ചുപിടിക്കൽ എന്നിവ കണക്കാക്കി പേസ്ലിപ്പുകൾ ഉണ്ടാക്കുന്നു.',
  'EPF to pay': 'അടയ്ക്കേണ്ട EPF',
  'SOCSO to pay': 'അടയ്ക്കേണ്ട SOCSO',
  'EIS to pay': 'അടയ്ക്കേണ്ട EIS',
  'EPF': 'EPF',
  'SOCSO': 'SOCSO',
  'EIS': 'EIS',
  'Employer pays on top': 'കമ്പനി അധികമായി അടയ്ക്കുന്നത്',
  'Housing allowance (₹)': 'ഭവന അലവൻസ് (₹)',
  'EPF (KWSP)': 'EPF (KWSP)',
  'SOCSO and EIS': 'SOCSO, EIS',
  'On pay up to ₹6,000 a month': 'മാസം ₹6,000 വരെയുള്ള ശമ്പളത്തിൽ',
  'EPF, SOCSO and EIS: workers {ee} · employer {er}': 'EPF, SOCSO, EIS: തൊഴിലാളികൾ {ee} · കമ്പനി {er}',
  'EPF, SOCSO and EIS are worked out on the wages in this sheet. They are due on a month\'s wages, so check them against the month\'s total before paying them over. A worker with a PLKS permit on file is counted as foreign: EPF 2% each, SOCSO as for a local worker, no EIS.': 'EPF, SOCSO, EIS ഈ ഷീറ്റിലെ കൂലിയിൽ കണക്കാക്കിയതാണ്. ഇവ മാസക്കൂലിയിലാണ് അടയ്ക്കേണ്ടത്, അതിനാൽ അടയ്ക്കുന്നതിന് മുമ്പ് മാസത്തെ ആകെ തുകയുമായി ഒത്തുനോക്കുക. PLKS പെർമിറ്റ് രേഖപ്പെടുത്തിയ തൊഴിലാളിയെ വിദേശിയായി കണക്കാക്കുന്നു: EPF ഇരുഭാഗത്തും 2%, SOCSO നാട്ടുകാരനായ തൊഴിലാളിയുടേത് പോലെ, EIS ഇല്ല.',
  'Cut from pay: {items}': 'ശമ്പളത്തിൽ നിന്ന് പിടിച്ചത്: {items}',
  'Employer pays: {items}': 'കമ്പനി അടയ്ക്കുന്നത്: {items}',
  'Net pay {amount}': 'കൈയിൽ കിട്ടുന്ന ശമ്പളം {amount}',
  // Forgot PIN: signing in to the cloud account again.
  'Forgot PIN?': 'PIN മറന്നോ?',
  'Confirm it is you': 'ഇത് നിങ്ങളാണെന്ന് ഉറപ്പാക്കുക',
  'To choose a new PIN, sign in again to {email}.': 'പുതിയ PIN തിരഞ്ഞെടുക്കാൻ {email} ൽ വീണ്ടും സൈൻ ഇൻ ചെയ്യുക.',
  'Use my password': 'എന്റെ പാസ്‌വേഡ് ഉപയോഗിക്കുക',
  'Email me a code': 'എനിക്ക് കോഡ് ഇമെയിൽ ചെയ്യുക',
  'We emailed a sign-in code to {email}.': '{email} ലേക്ക് ഒരു സൈൻ-ഇൻ കോഡ് ഇമെയിൽ ചെയ്തു.',
  'That password is not right.': 'ആ പാസ്‌വേഡ് ശരിയല്ല.',
  'That code is wrong or has expired.': 'ആ കോഡ് തെറ്റാണ് അല്ലെങ്കിൽ കാലഹരണപ്പെട്ടു.',
  'That is a different account. Use {email}.': 'അത് മറ്റൊരു അക്കൗണ്ടാണ്. {email} ഉപയോഗിക്കുക.',
  'That did not go through. Check the internet and try again.': 'അത് നടന്നില്ല. ഇന്റർനെറ്റ് പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.',
  'This phone is not signed in to the cloud': 'ഈ ഫോൺ ക്ലൗഡിൽ സൈൻ ഇൻ ചെയ്തിട്ടില്ല',
  'The data on this phone goes with the cloud account {email}. Sign in to it to keep the data and choose a new PIN.': 'ഈ ഫോണിലെ ഡാറ്റ {email} എന്ന ക്ലൗഡ് അക്കൗണ്ടിന്റേതാണ്. ഡാറ്റ നിലനിർത്താനും പുതിയ PIN തിരഞ്ഞെടുക്കാനും അതിൽ സൈൻ ഇൻ ചെയ്യുക.',
  'The data on this phone was never linked to a cloud account, so signing in cannot show that it is yours. Without the PIN, the only way in is to erase this phone and start over.': 'ഈ ഫോണിലെ ഡാറ്റ ഒരിക്കലും ഒരു ക്ലൗഡ് അക്കൗണ്ടുമായും ബന്ധിപ്പിച്ചിട്ടില്ല, അതിനാൽ സൈൻ ഇൻ ചെയ്താലും അത് നിങ്ങളുടേതാണെന്ന് കാണിക്കാനാവില്ല. PIN ഇല്ലാതെ അകത്ത് കടക്കാനുള്ള ഒരേയൊരു വഴി ഈ ഫോൺ മായ്ച്ച് വീണ്ടും തുടങ്ങുകയാണ്.',
  'Sign in to keep my data': 'സൈൻ ഇൻ ചെയ്ത് എന്റെ ഡാറ്റ നിലനിർത്തുക',
  'Erase this phone and start over': 'ഈ ഫോൺ മായ്ച്ച് വീണ്ടും തുടങ്ങുക',
  'Erase this phone?': 'ഈ ഫോൺ മായ്ക്കണോ?',
  'Everything on this phone that is not backed up to the cloud is lost for good: sites, workers, attendance, bills, photos and the rest. This cannot be undone.': 'ഈ ഫോണിൽ ക്ലൗഡിലേക്ക് ബാക്കപ്പ് ചെയ്യാത്തതെല്ലാം എന്നെന്നേക്കുമായി നഷ്ടപ്പെടും: സൈറ്റുകൾ, തൊഴിലാളികൾ, ഹാജർ, ബില്ലുകൾ, ഫോട്ടോകൾ, ബാക്കിയെല്ലാം. ഇത് തിരിച്ചെടുക്കാനാവില്ല.',
  'To confirm, type {word} below.': 'ഉറപ്പാക്കാൻ താഴെ {word} എന്ന് ടൈപ്പ് ചെയ്യുക.',
  'You can also type {word}.': 'നിങ്ങൾക്ക് {word} എന്നും ടൈപ്പ് ചെയ്യാം.',
  'Confirmation word': 'ഉറപ്പാക്കൽ വാക്ക്',
  'Erase everything': 'എല്ലാം മായ്ക്കുക',
  'ERASE': 'മായ്ക്കുക',
  'The phone could not be erased. Close FieldOS, open it again and try once more.': 'ഫോൺ മായ്ക്കാനായില്ല. FieldOS അടച്ച്, വീണ്ടും തുറന്ന്, ഒരിക്കൽ കൂടി ശ്രമിക്കുക.',
  '{amount}/hr': '{amount}/മണിക്കൂർ',
  '{amount} an hour': 'മണിക്കൂറിന് {amount}',
  'OT {h} h, {amount}': 'ഓവർടൈം {h} മണിക്കൂർ, {amount}',
  'Hi! I am Mitra, your site buddy': 'നമസ്കാരം! ഞാൻ Mitra, നിങ്ങളുടെ സൈറ്റ് കൂട്ടുകാരൻ',
  'Let me show you one day on a sample site, a two-storey house. It takes two minutes and does not touch your own data.': 'ഒരു സാമ്പിൾ സൈറ്റിലെ ഒരു ദിവസം ഞാൻ കാണിച്ചുതരാം: ഒരു ഇരുനില വീട്. രണ്ട് മിനിറ്റ് മതി, നിങ്ങളുടെ സ്വന്തം ഡാറ്റയെ ഇത് ബാധിക്കില്ല.',
  'Not sure where something is? Tap Ask FieldOS at the top and type or speak, like "add 500 for cement". It does the work and asks you to tap Save first.': 'എന്തെങ്കിലും എവിടെയാണെന്ന് ഉറപ്പില്ലേ? മുകളിലുള്ള FieldOS-നോട് ചോദിക്കുക ടാപ്പ് ചെയ്ത് "സിമന്റിന് 500 ചേർക്കുക" എന്നത് പോലെ ടൈപ്പ് ചെയ്യുകയോ പറയുകയോ ചെയ്യുക. അത് ജോലി ചെയ്യും, ആദ്യം സേവ് ടാപ്പ് ചെയ്യാൻ നിങ്ങളോട് ചോദിക്കും.',
  'Check workers in as they arrive, or mark the whole crew at once. Hours and overtime are worked out for you.': 'തൊഴിലാളികൾ എത്തുമ്പോൾ അവരെ ചെക്ക് ഇൻ ചെയ്യുക, അല്ലെങ്കിൽ മുഴുവൻ സംഘത്തെയും ഒരുമിച്ച് മാർക്ക് ചെയ്യുക. മണിക്കൂറുകളും ഓവർടൈമും നിങ്ങൾക്കായി കണക്കാക്കും.',
  'Every cost on site': 'സൈറ്റിലെ എല്ലാ ചെലവും',
  'Money received, money spent and the balance, by category. Client bills and tax invoices are made here too.': 'ലഭിച്ച പണം, ചെലവായ പണം, ബാക്കി എന്നിവ വിഭാഗം തിരിച്ച്. ക്ലയന്റ് ബില്ലുകളും ടാക്സ് ഇൻവോയ്സുകളും ഇവിടെ തന്നെ ഉണ്ടാക്കാം.',
  'Tap Speak report and just talk, in your language or in English. FieldOS writes the report, adds the day\'s numbers and shares it as a PDF.': 'റിപ്പോർട്ട് പറയുക ടാപ്പ് ചെയ്ത് നിങ്ങളുടെ ഭാഷയിലോ ഇംഗ്ലീഷിലോ സംസാരിച്ചാൽ മതി. FieldOS റിപ്പോർട്ട് എഴുതി, ആ ദിവസത്തെ കണക്കുകൾ ചേർത്ത്, PDF ആയി ഷെയർ ചെയ്യും.',
  'The wage sheet adds up each worker\'s pay, advances and what is still due, ready to pay or send to the office.': 'വേതന ഷീറ്റ് ഓരോ തൊഴിലാളിയുടെയും വേതനം, അഡ്വാൻസുകൾ, ഇനിയും നൽകാനുള്ളത് എന്നിവ കൂട്ടിക്കണക്കാക്കുന്നു, നൽകാനോ ഓഫീസിലേക്ക് അയയ്ക്കാനോ തയ്യാർ.',
  'Spending is {amount} over the BOQ budget.': 'ചെലവ് BOQ ബജറ്റിനേക്കാൾ {amount} കൂടുതലാണ്.',
  'Over budget on {item}: spent {spent} of {budget}.': 'ബജറ്റ് കവിഞ്ഞു, {item}: {budget}-ൽ {spent} ചെലവായി.',
  'Close to budget on {item}: {spent} of {budget} ({pct}%).': 'ബജറ്റിനോട് അടുത്തു, {item}: {budget}-ൽ {spent} ({pct}%).',
  '{amount} spent without a BOQ item.': 'BOQ ഇനമില്ലാതെ {amount} ചെലവായി.',
  'Purchase request': 'വാങ്ങൽ അഭ്യർത്ഥന',
  'Tasks show how far each job has got and what is slipping. The ground beam is late, so it is marked in red before anyone has to ask.': 'ഓരോ ജോലിയും എത്രത്തോളം ആയി, എന്താണ് പിന്നോട്ട് പോകുന്നത് എന്ന് ടാസ്കുകൾ കാണിക്കുന്നു. ഗ്രൗണ്ട് ബീം വൈകിയതിനാൽ, ആരെങ്കിലും ചോദിക്കുന്നതിന് മുമ്പേ അത് ചുവപ്പിൽ അടയാളപ്പെടുത്തുന്നു.',
};
